-- Migration 019: 14 neue Brett-Quests (jetzt 20), Folge-Quest „Medizin für Lene“, Quest-Folgen wirken aufs Dorf (dorf, zuzug, holz aus dem Dorflager).

create or replace function public.eco_effekt(d jsonb) returns text language plpgsql immutable as $$
declare k text; val numeric; parts text[];
begin
  for k, val in select key, value::numeric from jsonb_each_text(d) loop
    parts := parts || case
      when k = 'stimmung' and val > 0 then 'Die Stimmung im Dorf hebt sich.' when k = 'stimmung' and val < 0 then 'Die Stimmung im Dorf leidet.'
      when k = 'nahrung' and val >= 15 then 'Die Vorräte des Dorfes wachsen deutlich.' when k = 'nahrung' and val > 0 then 'Die Vorräte des Dorfes wachsen ein wenig.'
      when k = 'nahrung' and val <= -15 then 'Das Dorf verliert viel von seinen Vorräten.' when k = 'nahrung' and val < 0 then 'Das Dorf gibt etwas von seinen Vorräten ab.'
      when k = 'holz' and val > 0 then 'Im Lager liegt mehr Holz.' when k = 'holz' and val < 0 then 'Es wird Holz aus dem Lager gebraucht.'
      when k = 'stein' and val > 0 then 'Im Lager liegt mehr Stein.' when k = 'stein' and val < 0 then 'Es wird Stein aus dem Lager gebraucht.'
      when k = 'waren' and val > 0 then 'Das Dorf hat mehr Werkzeug und Waren.' when k = 'waren' and val < 0 then 'Das Dorf gibt Werkzeug und Waren her.' else null end;
  end loop;
  return array_to_string(parts, ' ');
end;
$$;

create or replace function public.q_apply(p_run_id bigint, f jsonb) returns text language plpgsql security definer set search_path = public as $$
declare r quest_runs; k text; v text; out text := ''; arm record; ctx jsonb; nid bigint; gst int; lt json; n int; vid bigint; zn npcs;
begin
  if f is null or f = '{}'::jsonb then return ''; end if;
  select * into r from quest_runs where id = p_run_id for update; ctx := q_ctx(r);
  select id into vid from villages where owner_id = r.player_id;
  perform q_apply_roles(r, f);
  if f ? 'flag' then update quest_runs set flags = flags || (select jsonb_object_agg(x, true) from jsonb_array_elements_text(f->'flag') x) where id = r.id; end if;
  if f ? 'item_plus' then for k, v in select * from jsonb_each_text(f->'item_plus') loop
    insert into player_items (player_id, item_id, menge) values (r.player_id, k, v::int) on conflict (player_id, item_id) do update set menge = player_items.menge + excluded.menge;
    out := out || ' Erhalten: ' || (select name from items where id = k) || case when v::int > 1 then ' ×' || v else '' end || '.'; end loop; end if;
  if f ? 'item_minus' then for k, v in select * from jsonb_each_text(f->'item_minus') loop update player_items set menge = greatest(0, menge - v::int) where player_id = r.player_id and item_id = k; end loop; end if;
  if f ? 'holz' and vid is not null then perform eco_add(vid, jsonb_build_object('holz', (f->>'holz')::numeric)); out := out || ' ' || eco_effekt(jsonb_build_object('holz', (f->>'holz')::numeric)); end if;
  if f ? 'dorf' and vid is not null then perform eco_add(vid, f->'dorf'); out := out || coalesce(' ' || nullif(eco_effekt(f->'dorf'), ''), ''); end if;
  if f ? 'zuzug' and vid is not null then
    if jsonb_typeof(f->'zuzug') = 'string' then
      select * into zn from npcs where lower(name) = lower(f->>'zuzug');
      if zn.id is not null and zn.village_id is null then perform eco_zuzug(vid, now(), zn.id); out := out || ' ' || zn.name || ' wohnt jetzt in deinem Dorf.';
      elsif zn.id is not null and zn.village_id is distinct from vid then out := out || ' ' || zn.name || ' hat inzwischen anderswo ein Zuhause gefunden.'; end if;
    else
      nid := eco_zuzug(vid, now());
      if nid is not null then out := out || ' ' || (select name from npcs where id = nid) || ' bleibt und zieht ins Dorf.'; end if;
    end if;
  end if;
  if (f ? 'begleiter_sym' or f ? 'begleiter_loy') and coalesce(array_length(r.begleiter, 1), 0) > 0 then
    foreach nid in array r.begleiter loop
      insert into npc_relations (npc_id, player_id, sympathy, loyalty) values (nid, r.player_id, 0, 0) on conflict do nothing;
      update npc_relations set sympathy = greatest(-100, least(100, sympathy + coalesce((f->>'begleiter_sym')::int, 0))), loyalty = greatest(0, least(100, loyalty + coalesce((f->>'begleiter_loy')::int, 0))), updated_at = now() where npc_id = nid and player_id = r.player_id;
    end loop; end if;
  if f ? 'notiz' and coalesce(array_length(r.begleiter, 1), 0) > 0 then
    insert into player_notes (player_id, npc_id, kind, text) values (r.player_id, r.begleiter[1], 'begegnung', left(q_fill(f->>'notiz', ctx), 500));
    insert into npc_memories (npc_id, player_id, kind, text, sympathy_delta) values (r.begleiter[1], r.player_id, 'gespraech', 'Wir haben zusammen ein Abenteuer erlebt. ' || q_fill(f->>'notiz', ctx), 0);
  end if;
  if f ? 'chronik' then insert into chronicle (player_id, key, text) values (r.player_id, f->'chronik'->>0, q_fill(f->'chronik'->>1, ctx)) on conflict do nothing; end if;
  if f ? 'journal' then insert into player_journal (player_id, kind, key, title, text) values (r.player_id, 'auftrag', f->'journal'->>0, f->'journal'->>1, f->'journal'->>2) on conflict do nothing; out := out || ' Tagebuch: ' || (f->'journal'->>1) || '.'; end if;
  if f ? 'begleiter_ab' and coalesce(array_length(r.begleiter, 1), 0) > 0 then update quest_runs set begleiter = begleiter[2:] where id = r.id; end if;
  if f ? 'gefahr' then
    gst := case when jsonb_typeof(f->'gefahr') = 'number' then (f->>'gefahr')::int else 1 end;
    select e.src, e.ref, e.schutz, e.unverwuestlich, coalesce(g.name, i.name) as name into arm
      from p_equipment(r.player_id) e left join player_gear g on e.src = 'gear' and g.id::text = e.ref left join items i on e.src = 'item' and i.id = e.ref
      where e.art = 'ruestung' and e.schutz > 0 order by e.schutz desc limit 1;
    if arm.name is not null and arm.schutz >= gst then
      out := out || ' Deine Rüstung (' || arm.name || ') fängt das Schlimmste ab.';
      if arm.src = 'gear' and not arm.unverwuestlich then
        update player_gear set zustand = greatest(0, zustand - 20) where id = arm.ref::bigint returning zustand into n;
        if n = 0 then out := out || ' Es ist jetzt beschädigt und schützt nicht mehr, bis es repariert wird.'; end if;
      end if;
    else
      update profiles set zustand = 'verletzt', zustand_bis = now() + interval '6 hours' where id = r.player_id;
      out := out || case when arm.name is not null then ' Selbst deine Rüstung (' || arm.name || ') hilft hier nicht.' else '' end || ' Du bist verletzt (Proben −2 für einige Stunden).';
    end if;
  end if;
  if f ? 'beute' and random() < coalesce((f->'beute'->>'chance')::numeric, 1) then
    lt := loot_roll(r.player_id, coalesce((f->'beute'->>'stufe')::int, 1), f->'beute'->>'art', (select titel from quest_templates where id = r.quest_id));
    out := out || coalesce(' ' || q_fill(f->'beute'->>'text', ctx), '') || ' Gefunden: ' || (lt->>'name') || ' (' || (lt->>'stufe') || ').';
    update quest_runs set letztes = coalesce(letztes, '{}'::jsonb) || jsonb_build_object('beute', lt) where id = r.id;
  end if;
  return trim(out);
end;
$$;
revoke execute on function public.eco_effekt(jsonb), public.q_apply(bigint, jsonb) from public, anon, authenticated;

-- Brun, der Bergmann aus Erzklamm (reserviert: zieht nur über die Lene-Quest ein)
insert into public.npcs (name, job, tier, look, village_id, traits, reserviert)
select 'Brun', 'Bergmann', 2, $j${"w": 0, "hat": "kappe", "top": "#4e4a42", "belt": "#3a2618", "hair": "#5a4030", "legs": "#3e362c", "prop": "spitzhacke", "skin": "#c08a62", "beard": "voll", "boots": "#2e241a", "hatColor": "#2e2a26", "hairStyle": "kurz"}$j$::jsonb, null, $j${"mut": 64, "gier": 20, "treue": 88, "fleiss": 82, "geselligkeit": 38}$j$::jsonb, true
where not exists (select 1 from public.npcs where lower(name) = 'brun');
insert into public.npc_profiles (npc_id, herkunft, ziel, angst, geheimnis, staerken, schwaechen, eigenart, sturheit, wissen)
select id, 'Ich komme aus Erzklamm, hinter dem Pass. Mein Vater war Bergmann, sein Vater auch. Seit dort die Mine eingestürzt ist, gibt es nur noch Rauch und Hunger.',
  'Dass Lene groß wird und nie in einen Stollen muss.', 'Dass ich Lene verliere, wie ich ihre Mutter verloren habe.',
  'Ich habe in der verlassenen Mine Silber gefunden und niemandem gesagt, wo genau.', 'zäh, ehrlich, hält Wort, kennt Stein wie kein Zweiter',
  'misstrauisch gegenüber Fremden, stur, redet ungern über sich', 'klopft beim Nachdenken mit den Fingerknöcheln auf Holz, als prüfe er einen Stollen', 1,
  array['mine','mine_silber','mine_pfad','erzklamm']
from public.npcs where lower(name) = 'brun' and not exists (select 1 from public.npc_profiles p join public.npcs n on n.id = p.npc_id where lower(n.name) = 'brun');

-- Folge-Quest
insert into public.quest_templates (id, titel, beschreibung, voraussetzung, art, def) values ('lene', 'Medizin für Lene',
  'Brun aus Erzklamm hat dir in der Mine vertraut. Seine Tochter Lene ist krank – vielleicht kannst du helfen.', '{"wissen":"brun_tochter"}', 'haupt', $q${"start": "aufbruch", "szenen": {"aufbruch": {"ort": "dorf", "text": "Erzklamm liegt einen halben Tagesmarsch hinter dem Pass, dort, wo das Tal eng wird und die Hänge grau sind vom Abraum. Irgendwo dort wartet Brun – und Lene. Du packst {mit} das Nötigste.", "optionen": [{"text": "Über den Pass gehen", "weiter": "reise"}, {"text": "Vorher Kräuter und Tücher einpacken", "wenn": {"item": "kraeutertasche"}, "weiter": "reise", "folgen": {"flag": ["kraeuter"]}, "ergebnis": "In deiner Kräutertasche klappern Fläschchen und getrocknete Bündel."}]}, "reise": {"ort": "wald", "text": "Der Weg führt über den Pass, vorbei am verschütteten Eingang der Mine. Danach wird der Wald lichter, die Bäume krumm, der Boden grau.", "reise": {"minuten": 3, "weiter": "erzklamm", "begegnung": {"chance": 0.5, "szenen": ["b_kumpel", "b_karren"]}}}, "b_kumpel": {"ort": "wald", "text": "Am Wegrand hocken drei ausgemergelte Männer mit Hacken über der Schulter. „Nach Erzklamm? Da gibt’s nichts mehr. Außer Husten.“ Einer mustert dein Bündel.", "optionen": [{"text": "Brot mit ihnen teilen", "weiter": "erzklamm", "ergebnis": "Sie essen schweigend. Dann sagt der Älteste: „Bruns Hütte ist die letzte am Bach. Grüß ihn. Er ist ein guter Kerl.“", "folgen": {"flag": ["weg_bekannt"], "dorf": {"nahrung": -2}}}, {"text": "Weitergehen, die Hand am Gürtel", "tag": "[Einschüchtern]", "probe": {"id": "einschuechtern", "dc": 10}, "erfolg": {"text": "Sie sehen weg. Niemand folgt dir.", "weiter": "erzklamm"}, "misserfolg": {"text": "Einer steht auf, setzt sich aber wieder, als er sieht, dass du nicht allein bist – oder es zumindest so aussieht.", "weiter": "erzklamm"}}]}, "b_karren": {"ort": "wald", "text": "Ein Karren steckt mit gebrochener Achse im Schlamm. Eine Frau zerrt fluchend an einem Maultier. Auf dem Karren: Säcke mit Kohle.", "optionen": [{"text": "Mit anpacken", "tag": "[Anpacken]", "probe": {"id": "anpacken", "dc": 11}, "erfolg": {"text": "Mit vereinten Kräften hebt ihr den Karren aus dem Loch. Die Frau wischt sich die Hände ab. „Die Kohle ist für den Heiler in Erzklamm. Oswin. Pass auf bei dem – er nimmt mehr, als er gibt.“", "folgen": {"flag": ["oswin_warnung"]}, "weiter": "erzklamm"}, "misserfolg": {"text": "Der Karren rührt sich kaum. Am Ende hilft ihr gemeinsam, ihn leer zu räumen und neu zu beladen. Es kostet Zeit.", "weiter": "erzklamm"}}, {"text": "Vorbeigehen", "weiter": "erzklamm"}]}, "erzklamm": {"ort": "dorf", "text": "Erzklamm ist halb leer. Rauch aus einer Schmelzhütte legt sich wie ein grauer Deckel über die Dächer. In der letzten Hütte am Bach brennt Licht. Brun öffnet – und erstarrt, als er dich erkennt.", "optionen": [{"text": "„Ich habe gesagt, ich helfe. Hier bin ich.“", "weiter": "lene", "ergebnis": "Bruns Kinn zittert. Er tritt beiseite und lässt dich hinein."}, {"text": "„Ich habe dir einen Platz in unserem Dorf versprochen.“", "wenn": {"wissen": "brun_kommt"}, "weiter": "lene", "folgen": {"flag": ["versprochen"]}, "ergebnis": "„Du hast es nicht vergessen“, sagt Brun leise. „Komm rein. Sieh sie dir erst an.“"}]}, "lene": {"ort": "dorf", "text": "Auf einem Strohsack unter einer Decke liegt ein Mädchen von vielleicht zehn Jahren, blass, mit roten Flecken auf den Wangen. Jeder Atemzug pfeift. Lene sieht dich an. „Bist du die Person aus der Mine? Papa erzählt jeden Abend davon.“", "optionen": [{"text": "Sie untersuchen", "tag": "[Heilkunde]", "probe": {"id": "heilkunde", "dc": 12, "mod": {"kraeuter": -2}}, "erfolg": {"text": "Lungenfieber. Kein Fluch, keine Seuche. Sie braucht Wärme, Alantwurzel gegen den Husten – und vor allem Luft ohne diesen Rauch.", "folgen": {"flag": ["diagnose"]}, "weiter": "beratung"}, "misserfolg": {"text": "Du hörst das Pfeifen, fühlst die heiße Stirn. Was es genau ist, kannst du nicht sagen.", "weiter": "beratung"}}, {"text": "{bb} soll sie ansehen", "tag": "[{bb}]", "wenn": {"begleiter_beruf": ["Heilerin", "Kräuterfrau", "Alchemist"]}, "weiter": "beratung", "ergebnis": "{bb} legt das Ohr an Lenes Rücken und lauscht lange. „Lungenfieber. Alantwurzel hilft gegen den Husten. Aber solange sie diesen Rauch atmet, wird es nicht besser.“", "folgen": {"flag": ["diagnose"], "begleiter_sym": 3}}, {"text": "Ihr eine Geschichte aus der Mine erzählen", "weiter": "beratung", "ergebnis": "Du erzählst vom Einsturz – ein bisschen heldenhafter, als es war. Lene lacht und hustet und lacht wieder. Brun dreht sich zur Wand.", "folgen": {"flag": ["vertrauen"]}}]}, "beratung": {"ort": "dorf", "text": "Brun zieht dich vor die Tür. „Oswin, der Heiler unten im Ort, hat einen Trank. Drei Silberstücke das Fläschchen. Ich habe noch eins. Für eins.“ Er lacht bitter.", "optionen": [{"text": "Zu Oswin gehen", "weiter": "oswin"}, {"text": "Selbst nach Alantwurzel suchen", "wenn": {"flag": "diagnose"}, "weiter": "suche"}, {"text": "„Der Rauch macht sie krank. Sie muss hier weg.“", "wenn": {"flag": "diagnose"}, "weiter": "umzug"}]}, "oswin": {"ort": "dorf", "text": "Oswins Stube ist warm, voller Tiegel und bunter Fläschchen. Er selbst ist rund und freundlich. „Der Trank? Wirkt Wunder. Drei Silber, nicht verhandelbar.“", "optionen": [{"text": "Einen Tropfen probieren", "tag": "[Heilkunde]", "probe": {"id": "heilkunde", "dc": 12, "mod": {"oswin_warnung": -2}}, "erfolg": {"text": "Honig, Wasser, ein Hauch Minze. Sonst nichts. Ein teures Bonbon.", "folgen": {"flag": ["betrug"]}, "weiter": "oswin_wahl"}, "misserfolg": {"text": "Süß und scharf. Kann sein, dass es hilft.", "weiter": "oswin_wahl"}}, {"text": "Ihm in die Augen sehen", "tag": "[Menschenkenntnis]", "probe": {"id": "menschenkenntnis", "dc": 13, "mod": {"oswin_warnung": -2}}, "erfolg": {"text": "Sein Lächeln ist eingeübt. Er glaubt selbst nicht an das, was er verkauft.", "folgen": {"flag": ["betrug"]}, "weiter": "oswin_wahl"}, "misserfolg": {"text": "Ein freundlicher Mann. Oder ein guter Schauspieler.", "weiter": "oswin_wahl"}}]}, "oswin_wahl": {"ort": "dorf", "text": "Oswin wartet, die Hände über dem Bauch gefaltet.", "optionen": [{"text": "„Honig und Wasser für drei Silber? Das hört gleich der ganze Ort.“", "wenn": {"flag": "betrug"}, "tag": "[Einschüchtern]", "probe": {"id": "einschuechtern", "dc": 12}, "erfolg": {"text": "Oswin wird bleich. Er schiebt dir einen Beutel echter Alantwurzel über den Tisch. „Das hier hilft wirklich. Und jetzt geh. Bitte.“", "folgen": {"flag": ["wurzel"]}, "weiter": "heilen"}, "misserfolg": {"text": "„Beweis es doch.“ Er schließt die Tür vor deiner Nase.", "weiter": "beratung"}}, {"text": "Mit Silbererz bezahlen", "wenn": {"item": "silbererz"}, "weiter": "heilen", "ergebnis": "Oswin wiegt das Erz in der Hand, nickt und gibt dir den Trank – und, als du ihn scharf ansiehst, noch ein Bündel Alantwurzel dazu.", "folgen": {"item_minus": {"silbererz": 1}, "flag": ["wurzel"]}}, {"text": "Feilschen", "tag": "[Feilschen]", "probe": {"id": "feilschen", "dc": 14}, "erfolg": {"text": "Am Ende bekommst du den Trank für Bruns letztes Silberstück – und eine Handvoll Wurzeln, „weil heute mein großzügiger Tag ist“.", "folgen": {"flag": ["wurzel", "trank"]}, "weiter": "heilen"}, "misserfolg": {"text": "Oswin bleibt hart. Brun gibt sein letztes Silber für ein einziges Fläschchen.", "folgen": {"flag": ["trank"]}, "weiter": "heilen"}}, {"text": "Gehen und selbst suchen", "wenn": {"flag": "diagnose"}, "weiter": "suche"}]}, "suche": {"ort": "wald", "text": "Alant wächst an feuchten, sonnigen Hängen. Hier ist alles grau – aber oberhalb der Abraumhalden, am alten Bachlauf, könnte es noch welchen geben.", "reise": {"minuten": 1, "weiter": "halde"}}, "halde": {"ort": "mine", "text": "Am Rand der Halden, zwischen Geröll und Brennnesseln, ragen gelbe Blütenköpfe auf. Der Hang darunter ist locker.", "optionen": [{"text": "Vorsichtig hinüberklettern", "tag": "[Flink]", "probe": {"id": "flink", "dc": 12}, "erfolg": {"text": "Du gräbst drei kräftige Wurzeln aus, ohne dass ein Stein ins Rollen kommt.", "folgen": {"flag": ["wurzel"]}, "weiter": "heilen"}, "misserfolg": {"text": "Der Hang rutscht. Du kommst mit den Wurzeln zurück – und einem aufgeschlagenen Knie.", "folgen": {"flag": ["wurzel"], "gefahr": 1}, "weiter": "heilen"}}, {"text": "{bb} hält dich am Seil", "tag": "[{bb}]", "wenn": {"begleiter": true}, "weiter": "heilen", "ergebnis": "{bb} stemmt die Füße in den Boden, du lehnst dich weit hinaus. Drei Wurzeln, sauber geborgen.", "folgen": {"flag": ["wurzel"], "begleiter_sym": 2}}]}, "heilen": {"ort": "dorf", "text": "Zurück in Bruns Hütte. Lene schläft unruhig.", "optionen": [{"text": "Einen Sud aus der Alantwurzel kochen", "wenn": {"flag": "wurzel"}, "weiter": "nacht", "folgen": {"flag": ["sud"]}}, {"text": "Ihr Oswins Trank geben", "wenn": {"flag": "trank", "nicht_flag": "wurzel"}, "weiter": "nacht"}]}, "nacht": {"ort": "feuer", "text": "Die Nacht ist lang. Brun und du sitzt am Herd, horcht auf jeden Atemzug. Gegen Morgen …", "optionen": [{"text": "… nach Lene sehen", "wenn": {"flag": "sud"}, "weiter": "morgen_gut", "ergebnis": "Das Pfeifen ist leiser. Das Fieber ist gesunken. Lene schläft tief und ruhig, zum ersten Mal seit Wochen, sagt Brun."}, {"text": "… nach Lene sehen", "wenn": {"nicht_flag": "sud"}, "weiter": "morgen_schwach", "ergebnis": "Lene schläft. Der Trank hat sie beruhigt, aber das Pfeifen ist noch da."}]}, "morgen_gut": {"ort": "dorf", "text": "Brun steht in der Tür und sieht auf den Rauch über Erzklamm. „Es wird ihr besser gehen. Aber wenn sie hierbleibt, kommt es wieder. Jeden Winter.“", "optionen": [{"text": "„Dann kommt mit zu uns. Bei uns ist die Luft klar.“", "weiter": "umzug"}, {"text": "„Ihr müsst selbst entscheiden. Ich lasse euch die Wurzeln da.“", "weiter": "ende_bleiben"}]}, "morgen_schwach": {"ort": "dorf", "text": "Brun reibt sich übers Gesicht. „Es reicht nicht. Ich sehe es.“", "optionen": [{"text": "„Hier wird sie nicht gesund. Kommt mit zu uns.“", "weiter": "umzug"}, {"text": "„Ich suche Alantwurzel.“", "weiter": "suche"}]}, "umzug": {"ort": "dorf", "text": "Brun sieht sich in der Hütte um. Das Werkzeug seines Vaters, der Tisch, den er selbst gezimmert hat. „Alles, was ich bin, ist hier. Und alles, was ich habe, ist sie.“", "optionen": [{"text": "„Wir brauchen jemanden, der Stein bricht. Und Lene braucht Luft.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 12, "mod": {"versprochen": -3, "vertrauen": -2, "sud": -1}}, "erfolg": {"text": "Brun atmet lange aus. Dann nickt er. „Gib uns zwei Tage zum Packen.“ Lene, halb wach, flüstert: „Gibt es da Pferde?“", "weiter": "ende_umzug"}, "misserfolg": {"text": "„Ich kann nicht. Noch nicht.“", "weiter": "ende_bleiben"}}, {"text": "Lene selbst fragen", "wenn": {"flag": "vertrauen"}, "weiter": "ende_umzug", "ergebnis": "Lene setzt sich auf. „Papa. Ich will dahin, wo die Person aus der Mine wohnt.“ Brun lacht und weint gleichzeitig und hebt die Hände. „Na gut. Na gut.“"}]}, "ende_umzug": {"ort": "dorf", "ende": true, "text": "Zwei Tage später rumpelt ein Karren ins Dorf. Brun lenkt, Lene sitzt in Decken gewickelt obenauf und zeigt auf alles. Brun bezieht ein Lager am Dorfrand – und bricht schon am nächsten Morgen Stein.", "folgen": {"zuzug": "Brun", "chronik": ["lene_umzug", "Brun und seine Tochter Lene sind aus Erzklamm in unser Dorf gezogen. Lene geht es besser."], "journal": ["lene_hier", "Lene im Dorf", "Lene, Bruns Tochter, lebt jetzt bei uns. Die klare Luft tut ihr gut. Brun bricht Stein für das Dorf."], "dorf": {"stimmung": 3}, "beute": {"stufe": 2, "chance": 0.6, "text": "Beim Abladen drückt dir Lene etwas in die Hand, das sie in Erzklamm im Bach gefunden hat. „Für dich. Weil du gekommen bist.“"}}}, "ende_bleiben": {"ort": "dorf", "ende": true, "text": "Du machst dich auf den Heimweg. Am Bach drehst du dich noch einmal um: Lene winkt aus dem Fenster, Brun steht daneben. Vielleicht sieht man sich wieder.", "folgen": {"chronik": ["lene_geholfen", "Ich war in Erzklamm und habe Brun geholfen, seine kranke Tochter Lene zu pflegen."], "journal": ["lene_erzklamm", "Lene in Erzklamm", "Lene geht es vorerst besser. Aber der Rauch in Erzklamm macht sie jeden Winter krank. Brun weiß, wo er uns findet."]}}}}$q$::jsonb)
on conflict (id) do update set titel = excluded.titel, beschreibung = excluded.beschreibung, voraussetzung = excluded.voraussetzung, art = excluded.art, def = excluded.def;

-- Brett-Vorlagen (alle 20)
insert into public.quest_templates (id, titel, beschreibung, kurz, art, schwierigkeit, rollen, def)
select e->>'id', e->>'titel', e->>'kurz', e->>'kurz', 'brett', (e->>'schwierigkeit')::int, e->'rollen', e->'def' from jsonb_array_elements($q$[{"id":"b_vorrat","titel":"Der verschwundene Vorrat","kurz":"{A} vermisst einen Sack Saatgut aus dem Vorratsschuppen. Jemand im Dorf muss ihn genommen haben.","schwierigkeit":1,"rollen":{"A":"Bestohlene Person","B":"Verdächtige Person","C":"Zeuge"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} steht vor dem offenen Schuppen, die Hände in die Hüften gestemmt. „Ein ganzer Sack Saatgut. Weg. Ohne den wird mein Feld im Frühjahr kahl bleiben.“","optionen":[{"text":"„Ich finde heraus, wer das war.“","weiter":"spuren"},{"text":"„Beruhig dich erst mal. Wir finden ihn.“","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":10},"erfolg":{"text":"{A} atmet durch. „Du hast recht. Ich hab mich da reingesteigert.“","folgen":{"sym":{"A":2}},"weiter":"spuren"},"misserfolg":{"text":"„Beruhigen? Das ist mein Winter, der da fehlt!“","weiter":"spuren"}}]},"spuren":{"ort":"dorf","text":"Im Staub vor dem Schuppen sind Spuren, und an der Tür hängt ein Faden grober, brauner Wolle.","optionen":[{"text":"Den Spuren folgen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":11},"erfolg":{"text":"Die Spuren führen zum Haus von {B} – und dort, halb unter Stroh versteckt, liegt der Sack.","folgen":{"flag":["beweis"]},"weiter":"entdeckt"},"misserfolg":{"text":"Die Spuren verlieren sich zwischen den Häusern.","weiter":"zeuge"}},{"text":"Herumfragen, wer etwas gesehen hat","weiter":"zeuge"}]},"zeuge":{"ort":"dorf","text":"{C} kratzt sich am Kinn. „Gestern Abend? Da hab ich {B} mit einem Sack über der Schulter gesehen. Hab mir nichts dabei gedacht.“","optionen":[{"text":"Zu {B} gehen","weiter":"entdeckt","folgen":{"merkt":{"C":"Ich habe {held} erzählt, was ich gesehen habe. Hoffentlich war das richtig."}}}]},"entdeckt":{"ort":"dorf","text":"{B} sieht dich kommen und wird blass. „Ich … meine Kinder hatten Hunger. Ich wollte es zurückgeben, sobald ich kann. Bitte sag es nicht {A}.“","optionen":[{"text":"Lügt {B}?","tag":"[Menschenkenntnis]","wenn":{"nicht_flag":"geprueft"},"probe":{"id":"menschenkenntnis","dc":11},"erfolg":{"text":"Die Angst ist echt. In der Küche steht ein leerer Topf.","folgen":{"flag":["geprueft","wahrheit"]},"weiter":"entdeckt"},"misserfolg":{"text":"Du kannst es nicht sagen.","folgen":{"flag":["geprueft"]},"weiter":"entdeckt"}},{"text":"Den Sack zurückbringen und {A} die Wahrheit sagen","weiter":"ende_wahrheit","ergebnis":"{A} nimmt den Sack schweigend entgegen. Dann geht {A} hinüber zu {B}. Was die beiden reden, hörst du nicht.","folgen":{"sym":{"A":4,"B":-4},"merkt":{"A":"{held} hat mein Saatgut gefunden und mir die Wahrheit über {B} gesagt.","B":"{held} hat mich verraten, obwohl ich gefleht habe."},"chronik":["brett_vorrat_wahrheit","Ich habe herausgefunden, dass {B} das Saatgut von {A} genommen hat – und es offen gesagt."]}},{"text":"Den Sack heimlich zurücklegen und schweigen","weiter":"ende_still","ergebnis":"In der Nacht stellst du den Sack zurück in den Schuppen. {A} findet ihn am Morgen und hält es für ein Wunder.","folgen":{"sym":{"A":1,"B":6},"merkt":{"B":"{held} hat geschwiegen und mich gerettet. Das vergesse ich nicht."},"chronik":["brett_vorrat_still","Ich habe für {B} geschwiegen und das Saatgut heimlich zurückgebracht."]}},{"text":"„Wir gehen zusammen zu {A}. Du erklärst es selbst.“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":12,"mod":{"wahrheit":-2}},"erfolg":{"text":"{B} nickt zitternd. Vor {A} bricht {B} in Tränen aus. {A} schweigt lange – dann bietet {A} an, das Saatgut zu teilen.","folgen":{"sym":{"A":4,"B":4},"merkt":{"A":"{held} hat dafür gesorgt, dass {B} ehrlich zu mir war.","B":"{held} hat mir geholfen, das Richtige zu tun."},"chronik":["brett_vorrat_versoehnt","{A} und {B} haben sich versöhnt – ich habe sie zusammengebracht."]},"weiter":"ende_gut"},"misserfolg":{"text":"{B} schüttelt den Kopf. „Das kann ich nicht.“ Du bringst den Sack allein zurück.","folgen":{"sym":{"A":2,"B":-2}},"weiter":"ende_wahrheit"}}]},"ende_wahrheit":{"ort":"dorf","ende":true,"text":"Das Saatgut ist zurück. Im Dorf wird man darüber reden.","folgen":{"beute":{"stufe":1,"chance":0.6,"text":"Am Abend steht {A} vor deiner Tür und drückt dir zum Dank etwas in die Hand, das lange im Schuppen lag."}}},"ende_still":{"ort":"dorf","ende":true,"text":"Ein Geheimnis mehr, das du trägst. Belohnt wirst du dafür nicht – aber {B} wird es dir nicht vergessen."},"ende_gut":{"ort":"dorf","ende":true,"text":"Manchmal ist ein Streit der Anfang von etwas Besserem.","folgen":{"beute":{"stufe":1,"chance":0.8,"text":"{A} und {B} haben zusammengelegt und schenken dir etwas – als Dank dafür, dass du sie zusammengebracht hast."}}}}}},{"id":"b_brief","titel":"Ein Brief für die Mühle","kurz":"{A} bittet dich, einen versiegelten Brief zur Mühle am Bach zu bringen. Persönlich, sagt {A}, und schnell.","schwierigkeit":1,"rollen":{"A":"Absender","B":"Empfänger"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} drückt dir einen gefalteten Brief mit einem Wachssiegel in die Hand. „Für {B}. Gib ihn niemand anderem. Und … lies ihn nicht.“","optionen":[{"text":"Losgehen","weiter":"weg"}]},"weg":{"ort":"wald","text":"Der Pfad zur Mühle folgt dem Bach. Das Wasser glitzert, irgendwo klopft ein Specht.","reise":{"minuten":1,"weiter":"zweifel","begegnung":{"chance":0.3,"szenen":["b_haendler","b_wanderer"]}}},"b_haendler":{"ort":"wald","text":"Ein Händler hockt am Wegrand und flickt seinen Karren. „Hilf mir kurz, Freund? Das Rad will nicht.“","optionen":[{"text":"Mit anpacken","tag":"[Anpacken]","probe":{"id":"anpacken","dc":10},"erfolg":{"text":"Das Rad sitzt. Der Händler drückt dir zum Dank etwas in die Hand.","folgen":{"beute":{"stufe":1,"chance":1,"text":"„Für deine Mühe“, sagt er und gibt dir etwas aus seinem Karren."}},"weiter":"zweifel"},"misserfolg":{"text":"Ihr flucht beide, aber am Ende hält es irgendwie.","weiter":"zweifel"}},{"text":"Keine Zeit, der Brief eilt","weiter":"zweifel"}]},"b_wanderer":{"ort":"wald","text":"Ein alter Mann sitzt auf einem Stein. „Zur Mühle? Grüß mir das Wasserrad. Wir sind zusammen alt geworden.“ Er lacht leise.","optionen":[{"text":"Ein Stück mit ihm reden","weiter":"zweifel","ergebnis":"Er erzählt von früher, als die Mühle noch drei Räder hatte."}]},"zweifel":{"ort":"wald","text":"Kurz vor der Mühle löst sich das Siegel ein wenig. Man könnte hineinschauen, ohne dass es jemand merkt.","optionen":[{"text":"Hineinschauen","tag":"[Flink]","probe":{"id":"flink","dc":11},"erfolg":{"text":"Du liest: „Ich habe es nie vergessen. Komm zum Fest. Bitte.“ Du klebst das Siegel sauber wieder zu.","folgen":{"flag":["gelesen"]},"weiter":"muehle"},"misserfolg":{"text":"Das Siegel bricht ganz. Jetzt sieht man, dass jemand den Brief geöffnet hat.","folgen":{"flag":["gelesen","siegel_kaputt"]},"weiter":"muehle"}},{"text":"Den Brief ungelesen lassen","weiter":"muehle","folgen":{"flag":["treu"]}}]},"muehle":{"ort":"dorf","text":"{B} wischt sich das Mehl von den Händen und nimmt den Brief. Als {B} den Absender erkennt, wird es still.","optionen":[{"text":"Abwarten","wenn":{"nicht_flag":"siegel_kaputt"},"weiter":"antwort"},{"text":"„Das Siegel war schon kaputt, als …“","tag":"[Überreden]","wenn":{"flag":"siegel_kaputt"},"probe":{"id":"ueberreden","dc":13},"erfolg":{"text":"{B} glaubt dir – oder will dir glauben.","weiter":"antwort"},"misserfolg":{"text":"{B} sieht dich lange an. „Du hast ihn gelesen.“","folgen":{"sym":{"B":-4,"A":-3},"merkt":{"B":"{held} hat meinen Brief gelesen. Neugieriges Volk."}},"weiter":"antwort"}},{"text":"Die Wahrheit sagen: „Ich habe hineingeschaut. Es tut mir leid.“","wenn":{"flag":"gelesen"},"weiter":"antwort","ergebnis":"{B} schnaubt – dann lächelt {B} schief. „Wenigstens ehrlich.“","folgen":{"sym":{"B":1}}}]},"antwort":{"ort":"dorf","text":"{B} schreibt ein paar Zeilen auf die Rückseite und faltet den Brief neu. „Bring ihn zurück. Und sag {A} … nein. Bring ihn einfach.“","optionen":[{"text":"Zurück zu {A}","weiter":"ende","folgen":{"sym":{"A":4,"B":2},"merkt":{"A":"{held} hat meinen Brief zu {B} gebracht – und eine Antwort mitgebracht.","B":"{held} hat mir einen Brief von {A} gebracht. Nach all den Jahren."},"chronik":["brett_brief","Ich habe einen Brief zwischen {A} und {B} getragen. Was darin stand, war wichtig."]}}]},"ende":{"ort":"dorf","ende":true,"text":"{A} liest die Antwort und dreht sich weg, damit du die Augen nicht siehst. „Danke“, sagt {A} leise.","folgen":{"beute":{"stufe":1,"chance":0.6,"text":"Dann holt {A} etwas aus einer alten Truhe. „Nimm. Bei mir liegt es nur herum.“"}}}}}},{"id":"b_grenzstein","titel":"Streit um den Grenzstein","kurz":"{A} und {B} streiten, wem das Stück Land am alten Grenzstein gehört. Das Dorf erwartet, dass jemand entscheidet.","schwierigkeit":2,"rollen":{"A":"Streitpartei","B":"Streitpartei","C":"Älteste Stimme"},"def":{"start":"streit","szenen":{"streit":{"ort":"dorf","text":"Am Feldrand stehen sich {A} und {B} gegenüber. „Der Stein stand immer hier!“ – „Weil du ihn letzten Herbst versetzt hast!“ Ein paar Leute sehen zu.","optionen":[{"text":"Dazwischengehen und beide beruhigen","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":12},"erfolg":{"text":"Die Stimmen werden leiser. Beide sind bereit, dich anzuhören.","folgen":{"flag":["ruhig"]},"weiter":"pruefen"},"misserfolg":{"text":"„Halt dich raus!“, rufen beide gleichzeitig. Immerhin sind sie sich da einig.","weiter":"pruefen"}},{"text":"„Ich sehe mir den Stein an.“","weiter":"pruefen"}]},"pruefen":{"ort":"wald","text":"Der Grenzstein ist alt und bemoost. Am Boden daneben sieht man eine frische Kuhle, als hätte man ihn bewegt – oder als hätten Wildschweine gewühlt.","optionen":[{"text":"Den Boden genau untersuchen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":13},"erfolg":{"text":"Die Kuhle stammt von Schweinen. Aber unter dem Moos zeigt eine verwitterte Kerbe in Richtung von {B}s Feld.","folgen":{"flag":["kerbe"]},"weiter":"wissen"},"misserfolg":{"text":"Du wirst nicht schlau daraus.","weiter":"wissen"}},{"text":"Die alten Zeichen auf dem Stein deuten","tag":"[Altes Wissen]","probe":{"id":"altes_wissen","dc":12},"erfolg":{"text":"Das Zeichen ist ein altes Flurmal: Die Grenze verläuft entlang der Kerbe – und die zeigt zu {B}.","folgen":{"flag":["kerbe","gedeutet"]},"weiter":"wissen"},"misserfolg":{"text":"Die Zeichen sind zu verwittert.","weiter":"wissen"}},{"text":"{C} fragen, wie es früher war","weiter":"aelteste"}]},"aelteste":{"ort":"dorf","text":"{C} lehnt sich zurück. „Als ich jung war, hat der Stein weiter drüben gestanden. Aber das ist lange her, und das Gedächtnis ist ein Lügner.“","optionen":[{"text":"Zurück zum Feld","weiter":"wissen","folgen":{"flag":["erinnerung"]}}]},"wissen":{"ort":"dorf","text":"Alle warten auf dein Wort. {A} sieht dich hoffnungsvoll an, {B} mit verschränkten Armen.","optionen":[{"text":"Für {B} entscheiden: Die alte Kerbe zählt.","wenn":{"flag":"kerbe"},"weiter":"ende","ergebnis":"{B} nickt zufrieden. {A} schluckt – aber gegen das alte Zeichen kann niemand etwas sagen.","folgen":{"beute":{"stufe":2,"chance":0.7,"text":"{B} drückt dir später etwas in die Hand. „Für deinen klaren Blick.“"},"sym":{"B":5,"A":-1,"C":2},"merkt":{"B":"{held} hat gerecht entschieden – mit Beweis.","A":"{held} hat gegen mich entschieden. Aber mit Beweis."},"chronik":["brett_grenze_beweis","Ich habe den Grenzstreit zwischen {A} und {B} mit einem alten Flurmal entschieden."]}},{"text":"Für {A} entscheiden – {A} braucht das Land dringender.","weiter":"ende","ergebnis":"{A} atmet auf. {B} spuckt aus und geht.","folgen":{"beute":{"stufe":2,"chance":0.7,"text":"{A} kommt am Abend vorbei und gibt dir etwas. „Das hab ich dir versprochen, wenn du zu mir hältst.“"},"sym":{"A":6,"B":-6},"merkt":{"A":"{held} hat zu mir gehalten.","B":"{held} hat mir mein Land genommen. Das merke ich mir."},"chronik":["brett_grenze_a","Im Grenzstreit habe ich mich auf die Seite von {A} gestellt."]}},{"text":"Teilen: Jeder bekommt die Hälfte, und beide pflügen gemeinsam.","tag":"[Überreden]","probe":{"id":"ueberreden","dc":14,"mod":{"ruhig":-2,"erinnerung":-1}},"erfolg":{"text":"Lange Stille. Dann streckt {A} die Hand aus. {B} schlägt ein – zögernd, aber ein.","folgen":{"beute":{"stufe":2,"chance":0.9,"text":"Beide legen zusammen und schenken dir etwas. „Ohne dich hätten wir uns die Köpfe eingeschlagen.“"},"sym":{"A":4,"B":4,"C":3},"merkt":{"A":"{held} hat einen Frieden gefunden, den ich nicht gesehen habe.","B":"{held} hat uns beide überredet. Klug."},"chronik":["brett_grenze_frieden","Ich habe den Grenzstreit zwischen {A} und {B} geschlichtet."]},"weiter":"ende"},"misserfolg":{"text":"„Teilen? Mit dem?“ Beide gehen im Zorn. Der Streit ist nicht vorbei.","folgen":{"sym":{"A":-2,"B":-2},"chronik":["brett_grenze_offen","Der Grenzstreit zwischen {A} und {B} schwelt weiter."]},"weiter":"ende"}}]},"ende":{"ort":"dorf","ende":true,"text":"Der Stein steht, wo er steht. Ob die Wunden heilen, wird sich zeigen."}}}},{"id":"b_fieber","titel":"Fieber im Dorf","kurz":"Das Kind von {A} glüht vor Fieber. Die Kräuter im Dorf sind aufgebraucht – im Wald wächst Weidenröschen, aber dort streunen Wölfe.","schwierigkeit":2,"rollen":{"A":"Elternteil","B":"Kundige Person"},"def":{"start":"krank","szenen":{"krank":{"ort":"dorf","text":"Im Halbdunkel der Hütte liegt ein Kind unter Fellen, das Gesicht nass vom Schweiß. {A} hält seine Hand. „{B} sagt, nur frisches Weidenröschen hilft noch.“","optionen":[{"text":"Das Kind selbst untersuchen","tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":12},"erfolg":{"text":"Du kühlst die Stirn mit nassen Tüchern und flößt Wasser ein. Das verschafft Zeit.","folgen":{"flag":["zeit"]},"weiter":"aufbruch"},"misserfolg":{"text":"Du weißt nicht genug darüber. Es bleibt nur der Wald.","weiter":"aufbruch"}},{"text":"„Ich hole die Kräuter.“","weiter":"aufbruch"}]},"aufbruch":{"ort":"wald","text":"Der Wald ist still und kalt. Irgendwo in den Senken soll das Weidenröschen wachsen.","reise":{"minuten":2,"weiter":"senke","begegnung":{"chance":0.5,"szenen":["woelfe"]}}},"woelfe":{"ort":"wald","gefahr":true,"text":"Zwei Wölfe treten aus dem Unterholz. Mager, hungrig, wachsam.","optionen":[{"text":"Warnschuss","tag":"[Bogen]","wenn":{"item":"bogen"},"probe":{"id":"flink","dc":10},"erfolg":{"text":"Der Pfeil fährt zwischen ihnen in den Boden. Sie fliehen.","weiter":"senke"},"misserfolg":{"text":"Daneben – einer springt dich an, bevor beide abhauen.","folgen":{"gefahr":1},"weiter":"senke"}},{"text":"Groß machen und brüllen","tag":"[Einschüchtern]","probe":{"id":"einschuechtern","dc":12},"erfolg":{"text":"Sie weichen zurück.","weiter":"senke"},"misserfolg":{"text":"Ein Biss, dann sind sie fort.","folgen":{"gefahr":1},"weiter":"senke"}},{"text":"{bb} kennt sich mit Tieren aus","tag":"[{bb}]","wenn":{"begleiter_beruf":["Jäger","Jägerin","Hirte","Falknerin"]},"weiter":"senke","ergebnis":"{bb} führt euch in weitem Bogen gegen den Wind vorbei.","folgen":{"begleiter_sym":2}}]},"senke":{"ort":"wald","text":"In einer feuchten Senke leuchten violette Blüten. Daneben: ein zweiter Strauch – größer, aber du bist nicht sicher, ob er nicht giftig ist.","optionen":[{"text":"Die Pflanzen genau bestimmen","tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":11},"erfolg":{"text":"Der kleine ist das Weidenröschen, der große ist Fingerhut – giftig. Gut, dass du hingesehen hast.","folgen":{"flag":["richtig"]},"weiter":"rueckweg"},"misserfolg":{"text":"Du nimmst von beiden. Sicher ist sicher.","folgen":{"flag":["beides"]},"weiter":"rueckweg"}},{"text":"Einfach den großen Strauch nehmen – mehr hilft mehr","weiter":"rueckweg","folgen":{"flag":["falsch"]}}]},"rueckweg":{"ort":"wald","text":"Mit vollen Taschen eilst du zurück.","reise":{"minuten":1,"weiter":"heilen"}},"heilen":{"ort":"dorf","text":"{B} nimmt dir die Pflanzen ab und betrachtet sie genau.","optionen":[{"text":"Abwarten","wenn":{"flag":"richtig"},"weiter":"ende_gut","ergebnis":"„Genau das“, murmelt {B} und braut einen Sud. In der Nacht sinkt das Fieber.","folgen":{"sym":{"A":8,"B":3},"merkt":{"A":"{held} hat meinem Kind das Leben gerettet.","B":"{held} kennt sich mit Kräutern aus. Das hätte ich nicht gedacht."},"chronik":["brett_fieber_gerettet","Ich habe Weidenröschen für das kranke Kind von {A} geholt. Es ist wieder gesund."]}},{"text":"Abwarten","wenn":{"flag":"beides"},"weiter":"ende_gut","ergebnis":"{B} sortiert den Fingerhut aus und schüttelt den Kopf. „Gut, dass du mir beides gebracht hast.“ Das Fieber sinkt bis zum Morgen.","folgen":{"sym":{"A":6,"B":2},"merkt":{"A":"{held} hat Kräuter für mein Kind geholt."},"chronik":["brett_fieber_gerettet","Ich habe Kräuter für das kranke Kind von {A} geholt. Es ist wieder gesund."]}},{"text":"Abwarten","wenn":{"flag":"falsch"},"weiter":"ende_knapp","ergebnis":"{B} wird bleich. „Das ist Fingerhut! Hätte ich das gekocht …“ {B} schickt dich noch einmal los, diesmal mit genauer Beschreibung. Erst im Morgengrauen sinkt das Fieber.","folgen":{"sym":{"A":2,"B":-2},"merkt":{"B":"{held} hätte beinahe Gift gebracht. Gut, dass ich nachgesehen habe."},"chronik":["brett_fieber_knapp","Ich hätte dem kranken Kind von {A} beinahe Gift gebracht. Es ging gerade noch gut."]}}]},"ende_gut":{"ort":"dorf","ende":true,"text":"Am nächsten Tag sitzt das Kind schon wieder am Feuer und fragt, wann du mal wieder Geschichten erzählst.","folgen":{"beute":{"stufe":2,"chance":1,"text":"{A} besteht darauf, dass du etwas annimmst. „Ohne dich … nimm es. Bitte.“"}}},"ende_knapp":{"ort":"dorf","ende":true,"text":"Das Kind wird gesund. Aber du wirst diese Nacht nicht so schnell vergessen."}}}},{"id":"b_hohlweg","titel":"Die Räuber vom Hohlweg","kurz":"Am Hohlweg werden Reisende überfallen. {A} hat dort Waren verloren und will, dass jemand die Räuber vertreibt – so oder so.","schwierigkeit":3,"rollen":{"A":"Geschädigte Person","B":"Wer die Gegend kennt"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} zeigt dir einen zerrissenen Beutel. „Drei Männer, vermummt. Sie haben alles genommen. Wenn das so weitergeht, kommt kein Händler mehr zu uns.“ {B} fügt leise hinzu: „Ich kenne einen Pfad oberhalb des Hohlwegs.“","optionen":[{"text":"Den oberen Pfad nehmen und die Räuber beobachten","weiter":"pfad"},{"text":"Offen den Hohlweg hinaufgehen – sollen sie nur kommen","weiter":"offen"}]},"pfad":{"ort":"wald","text":"Ihr klettert über Wurzeln und Geröll, bis ihr auf den Hohlweg hinabsehen könnt.","reise":{"minuten":2,"weiter":"lager"}},"offen":{"ort":"wald","text":"Der Hohlweg ist eng, die Böschungen hoch. Ein guter Ort für einen Hinterhalt.","reise":{"minuten":1,"weiter":"hinterhalt"}},"hinterhalt":{"ort":"wald","gefahr":true,"text":"Steine poltern. Drei Gestalten springen auf den Weg, Knüppel und ein rostiges Messer in den Händen. „Beutel her!“","optionen":[{"text":"Kämpfen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":14},"erfolg":{"text":"Du schlägst den ersten nieder, die anderen zögern. Einer lässt die Kapuze fallen – ein abgemagerter Junge.","folgen":{"flag":["gesiegt"]},"weiter":"entlarvt"},"misserfolg":{"text":"Ein Knüppel trifft dich hart. Aber dann rutscht einem die Kapuze herunter – ein Junge, kaum älter als fünfzehn.","folgen":{"gefahr":2},"weiter":"entlarvt"}},{"text":"Die Waffe ziehen und drohen","tag":"[Einschüchtern]","wenn":{"item_eines":["schwert","axt","dolch","saebel","speer"]},"probe":{"id":"einschuechtern","dc":12},"erfolg":{"text":"Stahl blitzt. Die drei weichen zurück, einer stolpert und verliert die Kapuze – ein Junge.","weiter":"entlarvt"},"misserfolg":{"text":"Sie greifen trotzdem an.","folgen":{"gefahr":2},"weiter":"entlarvt"}},{"text":"„Wartet. Warum tut ihr das?“","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":13},"erfolg":{"text":"Du siehst die zitternden Hände, die eingefallenen Wangen. Das sind keine Räuber. Das sind Hungrige.","folgen":{"flag":["verstanden"]},"weiter":"entlarvt"},"misserfolg":{"text":"Die Antwort ist ein Knüppelhieb.","folgen":{"gefahr":2},"weiter":"entlarvt"}}]},"lager":{"ort":"wald","text":"Unter euch, in einer Felsnische: ein armseliges Lager. Drei Männer – nein, zwei Männer und ein Junge – teilen sich einen dürren Hasen. Neben ihnen liegen {A}s Waren, unberührt.","optionen":[{"text":"Lauschen","tag":"[Schleichen]","probe":{"id":"flink","dc":12},"erfolg":{"text":"„Die Waren tauschen wir in Salzwacht gegen Korn. Dann gehen wir heim nach Erzklamm. Seit die Mine eingestürzt ist …“","folgen":{"flag":["verstanden","unentdeckt"]},"weiter":"entscheidung"},"misserfolg":{"text":"Ein Stein löst sich. Die drei springen auf.","weiter":"hinterhalt"}},{"text":"Ein Seil spannen und eine Falle am Ausgang der Nische stellen","tag":"[Anpacken]","wenn":{"item":"seil"},"probe":{"id":"anpacken","dc":11},"erfolg":{"text":"Die Falle sitzt. Wenn sie fliehen wollen, gehen sie zu Boden.","folgen":{"flag":["falle"]},"weiter":"entscheidung"},"misserfolg":{"text":"Das Seil verheddert sich.","weiter":"entscheidung"}},{"text":"Hinuntersteigen und sie stellen","weiter":"entscheidung"}]},"entlarvt":{"ort":"wald","text":"Der Älteste hebt die Hände. „Wir sind aus Erzklamm. Die Mine ist eingestürzt, es gibt kein Brot mehr. Wir wollten niemandem wehtun.“","optionen":[{"text":"Weiter","weiter":"entscheidung"}]},"entscheidung":{"ort":"wald","text":"Die Räuber sind in deiner Hand. {A}s Waren liegen da. Was jetzt?","optionen":[{"text":"Die Waren nehmen und sie laufen lassen","weiter":"ende","ergebnis":"Sie verschwinden zwischen den Bäumen. Einer dreht sich noch einmal um und nickt dir zu.","folgen":{"beute":{"stufe":3,"chance":0.8,"text":"Am Wegrand, wo sie gelagert haben, liegt etwas zurückgelassen – vielleicht absichtlich, als Dank."},"sym":{"A":4},"merkt":{"A":"{held} hat meine Waren zurückgebracht. Die Räuber sind fort."},"chronik":["brett_hohlweg_frei","Ich habe die Räuber vom Hohlweg laufen lassen – hungrige Leute aus Erzklamm."]}},{"text":"Sie gefangen nehmen und ins Dorf bringen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":12,"mod":{"falle":-4,"gesiegt":-2}},"erfolg":{"text":"Gefesselt führst du sie ins Dorf. {A} ist zufrieden. Was mit ihnen geschieht, entscheidet die Versammlung.","folgen":{"beute":{"stufe":3,"chance":1,"text":"{A} gibt dir als Belohnung etwas aus der zurückgewonnenen Ware."},"sym":{"A":6,"B":1},"merkt":{"A":"{held} hat die Räuber gefangen. Endlich Ruhe."},"chronik":["brett_hohlweg_gefangen","Ich habe die Räuber vom Hohlweg gefangen ins Dorf gebracht."]},"weiter":"ende"},"misserfolg":{"text":"Zwei entkommen, nur der Junge bleibt zurück. Er weint.","folgen":{"sym":{"A":3},"chronik":["brett_hohlweg_junge","Am Hohlweg habe ich einen jungen Räuber aus Erzklamm gefangen. Die anderen sind entkommen."]},"weiter":"ende"}},{"text":"„Kommt mit ins Dorf. Arbeit gegen Brot – das ist besser als der Hohlweg.“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":14,"mod":{"verstanden":-3}},"erfolg":{"text":"Lange Stille. Dann nickt der Älteste. „Wenn ihr uns nehmt, arbeiten wir.“ {A} ist skeptisch, aber die Waren sind zurück.","folgen":{"beute":{"stufe":3,"chance":1,"text":"Der Älteste gibt dir das Einzige, was er von zu Hause mitgenommen hat. „Damit du weißt, dass wir es ernst meinen.“"},"sym":{"A":2,"B":4},"merkt":{"A":"{held} hat die Räuber ins Dorf geholt. Ich traue ihnen nicht. Aber meine Waren sind zurück.","B":"{held} hat aus Räubern Arbeiter gemacht. Mutig."},"chronik":["brett_hohlweg_arbeit","Ich habe den Räubern vom Hohlweg Arbeit im Dorf angeboten. Sie kamen mit."],"journal":["erzklamm_fluechtlinge","Leute aus Erzklamm","Drei Männer aus Erzklamm arbeiten jetzt im Dorf. In Erzklamm herrscht Hunger, seit die Mine eingestürzt ist."]},"weiter":"ende"},"misserfolg":{"text":"„Damit ihr uns dann aufknüpft? Nein.“ Sie lassen die Waren fallen und fliehen.","folgen":{"sym":{"A":3}},"weiter":"ende"}}]},"ende":{"ort":"dorf","ende":true,"text":"Der Hohlweg ist wieder frei. Doch Erzklamm hungert, und das wird nicht die letzte Geschichte sein."}}}},{"id":"b_brand","titel":"Feuer in der Nacht","kurz":"Mitten in der Nacht brennt die Scheune von {A}. Jemand behauptet, {B} sei kurz vorher dort gewesen.","schwierigkeit":3,"rollen":{"A":"Geschädigte Person","B":"Beschuldigte Person","C":"Wer etwas gesehen hat"},"def":{"start":"feuer","szenen":{"feuer":{"ort":"dorf","gefahr":true,"text":"Rufe reißen dich aus dem Schlaf. Flammen schlagen aus dem Dach der Scheune von {A}. Drinnen brüllt das Vieh.","optionen":[{"text":"Hineinlaufen und das Vieh befreien","tag":"[Flink]","probe":{"id":"flink","dc":13},"erfolg":{"text":"Du reißt das Tor auf, die Tiere stürmen hinaus. Hinter dir kracht ein Balken.","folgen":{"flag":["vieh"],"sym":{"A":4}},"weiter":"loeschen"},"misserfolg":{"text":"Rauch, Hitze, ein brennender Balken streift dich. Aber die Tiere sind draußen.","folgen":{"flag":["vieh"],"sym":{"A":4},"gefahr":2},"weiter":"loeschen"}},{"text":"Eine Eimerkette organisieren","tag":"[Überreden]","probe":{"id":"ueberreden","dc":11},"erfolg":{"text":"Auf dein Kommando reihen sich alle auf. Eimer um Eimer fliegt ins Feuer.","folgen":{"flag":["kette"]},"weiter":"loeschen"},"misserfolg":{"text":"Alle laufen durcheinander.","weiter":"loeschen"}}]},"loeschen":{"ort":"dorf","text":"Im Morgengrauen ist das Feuer aus. Die Scheune ist eine schwarze Ruine. {C} zieht dich beiseite: „Ich hab {B} gestern Abend dort gesehen. Mit einer Laterne.“","optionen":[{"text":"Die Brandstelle untersuchen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":14},"erfolg":{"text":"Das Feuer begann nicht am Tor, wo {B} gestanden haben soll, sondern hinten, bei der Heuluke. Dort liegt eine umgekippte Öllampe – die von {A} selbst.","folgen":{"flag":["unfall"]},"weiter":"anklage"},"misserfolg":{"text":"Asche und Ruß. Nichts, was eindeutig wäre.","weiter":"anklage"}},{"text":"{C} genauer befragen","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":13},"erfolg":{"text":"{C} weicht deinem Blick aus. Zwischen {C} und {B} gibt es alten Streit – um ein Mädchen, vor Jahren.","folgen":{"flag":["groll"]},"weiter":"anklage"},"misserfolg":{"text":"{C} klingt sicher.","weiter":"anklage"}}]},"anklage":{"ort":"dorf","text":"Das halbe Dorf steht vor der Ruine. {A} zeigt auf {B}. „Warst du es?“ {B} schüttelt stumm den Kopf. Alle sehen dich an.","optionen":[{"text":"„Es war ein Unfall. Die Lampe von {A} lag an der Heuluke.“","wenn":{"flag":"unfall"},"weiter":"ende","ergebnis":"Ein Raunen. {A} wird rot und senkt den Kopf. {B} sieht dich an, als hättest du gerade ein Leben gerettet – und vielleicht hast du das.","folgen":{"beute":{"stufe":3,"chance":1,"text":"Am nächsten Morgen drückt dir {B} ein Erbstück in die Hand. „Du hast mir mehr gerettet als meinen Ruf.“"},"sym":{"B":8,"A":1,"C":-3},"merkt":{"B":"{held} hat bewiesen, dass ich es nicht war. Ich stehe in dieser Schuld.","C":"{held} hat mich vor allen bloßgestellt."},"chronik":["brett_brand_unfall","Ich habe bewiesen, dass der Brand bei {A} ein Unfall war – und {B} vor einer falschen Anklage bewahrt."]}},{"text":"„{C} hat einen alten Groll gegen {B}. Ich glaube {C} nicht.“","wenn":{"flag":"groll"},"weiter":"ende","ergebnis":"{C} läuft rot an und geht. Der Verdacht gegen {B} bleibt im Raum – aber er wackelt.","folgen":{"sym":{"B":4,"C":-5},"merkt":{"C":"{held} hat mich vor allen einen Lügner genannt.","B":"{held} hat zu mir gehalten."},"chronik":["brett_brand_groll","Beim Brand bei {A} habe ich die Aussage von {C} angezweifelt."]}},{"text":"„Ich weiß es nicht. Aber ohne Beweis wird niemand verurteilt.“","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":13},"erfolg":{"text":"Die Menge murrt, aber sie zerstreut sich. Niemand wird heute bestraft.","folgen":{"sym":{"B":3}},"weiter":"ende"},"misserfolg":{"text":"„Wer soll es sonst gewesen sein?“ {B} muss das Dorf für eine Weile meiden.","folgen":{"sym":{"B":-2,"A":2},"chronik":["brett_brand_verdacht","Nach dem Brand bei {A} fällt ein Schatten auf {B}."]},"weiter":"ende"}},{"text":"{B} beschuldigen","weiter":"ende","ergebnis":"{B} sieht dich an, als hättest du zugeschlagen. Dann geht {B}, ohne ein Wort.","folgen":{"sym":{"A":4,"B":-10,"C":3},"merkt":{"B":"{held} hat mich verurteilt, ohne Beweis. Das verzeihe ich nicht.","A":"{held} hat mir geholfen, den Schuldigen zu finden."},"chronik":["brett_brand_schuld","Ich habe {B} für den Brand bei {A} verantwortlich gemacht."]}}]},"ende":{"ort":"dorf","ende":true,"text":"Die Scheune muss neu gebaut werden. Und was in dieser Nacht gesagt wurde, bleibt."}}}},{"id":"b_ziege","titel":"Die Ziege im Hang","kurz":"Die beste Milchziege von {A} ist ausgebüxt und meckert irgendwo oben am Felshang.","schwierigkeit":1,"rollen":{"A":"Besitzer der Ziege","B":"Nachbar mit offenem Gatter"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} rennt dir entgegen, einen Strick in der Hand. „Hörst du das? Das ist Flocke. Irgendwer hat das Gatter offen gelassen, und jetzt hängt sie da oben im Hang fest.“","optionen":[{"text":"„Ich hole sie.“","weiter":"hang"},{"text":"„Wessen Gatter war offen?“","weiter":"hang","ergebnis":"{A} zuckt die Schultern. „Das von {B}, glaube ich. Aber erst die Ziege.“","folgen":{"flag":["gatter"]}}]},"hang":{"ort":"wald","text":"Flocke steht auf einem schmalen Absatz, unter ihr Geröll. Sie meckert empört, als wäre alles deine Schuld.","optionen":[{"text":"Hinaufklettern","tag":"[Flink]","probe":{"id":"flink","dc":10},"erfolg":{"text":"Griff um Griff kletterst du hinauf und legst ihr den Strick um den Hals.","weiter":"zurueck"},"misserfolg":{"text":"Ein Stein bricht weg, du rutschst ein Stück ab und schürfst dir die Hände auf. Beim zweiten Versuch klappt es.","weiter":"zurueck"}},{"text":"Mit dem Seil von oben sichern","tag":"[Seil]","wenn":{"item":"seil"},"weiter":"zurueck","ergebnis":"Du knotest das Seil um eine Kiefer und lässt dich sicher hinab. Flocke lässt sich ohne Murren hochziehen."},{"text":"Sie mit einer Handvoll Klee herunterlocken","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":11},"erfolg":{"text":"Flocke beäugt den Klee, dann dich, dann wieder den Klee. Schließlich hüpft sie Absatz für Absatz herunter.","weiter":"zurueck"},"misserfolg":{"text":"Flocke frisst lieber den Ginster neben sich. Du musst doch klettern – und kommst mit zerkratzten Armen zurück.","weiter":"zurueck"}}]},"zurueck":{"ort":"dorf","text":"{A} drückt Flocke an sich, als wäre sie ein Kind. Hinter dem Zaun steht {B} und tut sehr beschäftigt.","optionen":[{"text":"{B} auf das Gatter ansprechen","wenn":{"flag":"gatter"},"weiter":"ende","ergebnis":"{B} wird rot. „Ich war in Gedanken. Es tut mir leid.“ {B} verspricht {A} einen Krug Milch von den eigenen Tieren – und repariert das Gatter noch am selben Abend.","folgen":{"sym":{"A":3,"B":1},"merkt":{"B":"{held} hat mich auf das offene Gatter angesprochen, ohne Lärm darum zu machen."}}},{"text":"Nichts sagen – die Ziege ist ja zurück","weiter":"ende","folgen":{"sym":{"A":3,"B":2},"merkt":{"A":"{held} hat Flocke aus dem Hang geholt."}}},{"text":"Laut verkünden, dass {B} schuld war","weiter":"ende","ergebnis":"Ein paar Leute drehen sich um. {B} murmelt etwas und verschwindet im Haus.","folgen":{"sym":{"A":3,"B":-4},"merkt":{"B":"{held} hat mich wegen eines Gatters vor allen bloßgestellt."}}}]},"ende":{"ort":"dorf","ende":true,"text":"Am Abend steht ein kleiner Krug frische Ziegenmilch vor deiner Tür.","folgen":{"dorf":{"nahrung":4},"beute":{"stufe":1,"chance":0.3,"text":"Unter dem Krug liegt etwas, das {A} wohl lange aufbewahrt hat."}}}}}},{"id":"b_kraeuter","titel":"Kräuter vor dem Frost","kurz":"{A} will vor dem ersten Frost Heilkräuter am Waldsaum sammeln und hätte gern Begleitung.","schwierigkeit":1,"rollen":{"A":"Sammler","B":"Wer krank im Bett liegt"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} hat zwei Körbe dabei. „{B} hustet seit Tagen. Am Waldsaum wächst Lungenkraut und Weidenrinde gibt es am Bach. Kommst du mit? Allein dauert es ewig.“","optionen":[{"text":"Mitgehen","weiter":"weg"}]},"weg":{"ort":"wald","text":"Der Waldsaum liegt still im Morgendunst. Spinnweben glitzern zwischen den Farnen.","reise":{"minuten":1,"weiter":"lichtung","begegnung":{"chance":0.35,"szenen":["b_kaeuzchen"]}}},"b_kaeuzchen":{"ort":"wald","text":"Ein junger Waldkauz sitzt am Boden, ein Flügel hängt schief. Er faucht dich an.","optionen":[{"text":"Den Flügel schienen","tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":11},"erfolg":{"text":"Mit zwei Zweigen und einem Streifen Stoff richtest du den Flügel. Der Kauz hüpft ins Gebüsch und sieht dir nach.","folgen":{"sym":{"A":2},"notiz":"Wir haben unterwegs einen verletzten Waldkauz versorgt."},"weiter":"lichtung"},"misserfolg":{"text":"Er hackt dir in den Finger und flattert ungeschickt davon. Vielleicht schafft er es.","weiter":"lichtung"}},{"text":"Weitergehen – der Wald kümmert sich um seine Tiere","weiter":"lichtung"}]},"lichtung":{"ort":"wald","text":"Am Saum wachsen zwei Pflanzen dicht beieinander, beide mit gefleckten Blättern. Eine davon ist Lungenkraut. Die andere sieht fast gleich aus.","optionen":[{"text":"Die Pflanzen genau unterscheiden","tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":11},"erfolg":{"text":"Die echten Blätter sind rau wie eine Katzenzunge. Du sammelst nur die richtigen.","folgen":{"flag":["richtig"]},"weiter":"bach"},"misserfolg":{"text":"Du bist dir nicht sicher und sammelst von beiden.","folgen":{"flag":["gemischt"]},"weiter":"bach"}},{"text":"{A} entscheiden lassen","weiter":"bach","ergebnis":"{A} pflückt flink und sicher. „Rau wie eine Katzenzunge – das ist das richtige.“","folgen":{"flag":["richtig"]}}]},"bach":{"ort":"wald","text":"Am Bach schneidest du Weidenrinde. Auf dem Rückweg wird es kühl, der Atem dampft.","optionen":[{"text":"Zurück ins Dorf","weiter":"heim"}]},"heim":{"ort":"dorf","text":"{A} kocht aus den Kräutern einen bitteren Sud für {B}.","optionen":[{"text":"Den Sud vorher selbst prüfen","wenn":{"flag":"gemischt"},"tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":10},"erfolg":{"text":"Du riechst es sofort: Ein paar falsche Blätter sind dabei. Ihr kocht neu, diesmal sauber.","weiter":"ende_gut"},"misserfolg":{"text":"Riecht bitter. Aber das soll so sein, oder?","weiter":"ende_bauch"}},{"text":"Den Sud bringen","wenn":{"flag":"gemischt"},"weiter":"ende_bauch"},{"text":"Den Sud bringen","wenn":{"flag":"richtig"},"weiter":"ende_gut"}]},"ende_gut":{"ort":"dorf","ende":true,"text":"Zwei Tage später hustet {B} kaum noch und winkt dir vom Fenster aus zu. {A} hängt die übrigen Kräuter zum Trocknen unters Dach – genug für den ganzen Winter.","folgen":{"sym":{"A":3,"B":4},"merkt":{"B":"{held} hat mit {A} Kräuter für mich gesammelt, als ich krank war."},"dorf":{"stimmung":2},"beute":{"stufe":1,"chance":0.25,"text":"{B} besteht darauf, dir etwas zu schenken."}}},"ende_bauch":{"ort":"dorf","ende":true,"text":"{B} hat eine Nacht lang Bauchkrämpfe – dann hilft der Sud doch noch. {A} sagt nichts, sammelt am nächsten Tag aber allein nach.","folgen":{"sym":{"A":1,"B":1},"merkt":{"B":"{held} hat mir Kräuter gebracht. Mein Bauch hat es mir nicht gedankt."}}}}}},{"id":"b_brunnen","titel":"Der trübe Brunnen","kurz":"Das Wasser im Dorfbrunnen schmeckt seit Tagen faulig. {A} bittet dich, der Sache auf den Grund zu gehen.","schwierigkeit":1,"rollen":{"A":"Wer es bemerkt hat","B":"Wer oben am Bach arbeitet"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} hält dir einen Becher hin. Das Wasser ist leicht trüb und riecht nach nassem Laub und etwas Schlimmerem. „Der Brunnen wird vom Bach gespeist. Irgendwas stimmt oben nicht.“","optionen":[{"text":"Den Bach hinaufgehen","weiter":"bach"},{"text":"Erst in den Brunnen hinabsteigen","tag":"[Flink]","probe":{"id":"flink","dc":10},"erfolg":{"text":"Unten ist das Wasser klar, wo es aus dem Rohr kommt – das Übel kommt also von oben.","folgen":{"flag":["oben"]},"weiter":"bach"},"misserfolg":{"text":"Du rutschst ab und landest knietief im kalten Wasser. Gelernt hast du nur, dass es kalt ist.","weiter":"bach"}}]},"bach":{"ort":"wald","text":"Ein Stück oberhalb des Dorfes staut sich der Bach. Dort liegt ein verendeter Hirsch halb im Wasser. Und noch weiter oben, wo {B} arbeitet, schwimmt ein bräunlicher Film.","optionen":[{"text":"Den Hirsch untersuchen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":11},"erfolg":{"text":"Eine Wunde am Hals, verheilt – er ist alt und krank gestorben, nicht erlegt. Aber er liegt seit Tagen da.","folgen":{"flag":["hirsch"]},"weiter":"entscheidung"},"misserfolg":{"text":"Ein toter Hirsch. Mehr kannst du nicht sagen.","folgen":{"flag":["hirsch"]},"weiter":"entscheidung"}},{"text":"Zu {B} hinaufgehen","weiter":"b_gespraech"}]},"b_gespraech":{"ort":"wald","text":"{B} spült gerade Bottiche im Bach aus. „Ich mache das seit Jahren so. Das Wasser nimmt alles mit.“","optionen":[{"text":"„Das Dorf trinkt dieses Wasser.“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":11},"erfolg":{"text":"{B} hält inne. „Daran hab ich nie gedacht. Ich grabe eine Grube hinter dem Haus.“","folgen":{"flag":["b_einsicht"],"sym":{"B":1}},"weiter":"entscheidung"},"misserfolg":{"text":"„Ach was. Das bisschen.“","weiter":"entscheidung"}},{"text":"Zurück zum Hirsch","weiter":"entscheidung"}]},"entscheidung":{"ort":"wald","text":"Der Hirsch muss aus dem Wasser – und eigentlich auch der Rest.","optionen":[{"text":"Den Hirsch selbst herausziehen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":11},"erfolg":{"text":"Mit einem Ruck ziehst du das schwere Tier ans Ufer und bedeckst es mit Ästen. Der Füchse wegen.","weiter":"ende"},"misserfolg":{"text":"Zu schwer. Du holst Hilfe aus dem Dorf, und zu dritt schafft ihr es bis zum Abend.","weiter":"ende"}},{"text":"Die Leute im Dorf zusammenrufen","weiter":"ende","ergebnis":"Ein halbes Dutzend Leute kommt mit Seilen. Zusammen ist der Hirsch schnell aus dem Wasser.","folgen":{"dorf":{"stimmung":1}}}]},"ende":{"ort":"dorf","ende":true,"text":"Nach zwei Tagen ist das Wasser wieder klar. {A} trinkt den ersten Becher demonstrativ vor allen aus.","folgen":{"sym":{"A":3},"merkt":{"A":"{held} hat herausgefunden, warum unser Brunnen faulig war."},"chronik":["brett_brunnen","Ich habe den Brunnen des Dorfes wieder sauber bekommen."],"dorf":{"stimmung":2}}}}}},{"id":"b_waage","titel":"Die falsche Waage","kurz":"Ein fahrender Händler hat {A} beim Tausch übers Ohr gehauen, glaubt {A}. Er lagert noch am Dorfrand.","schwierigkeit":1,"rollen":{"A":"Wer betrogen wurde","B":"Wer gern handelt"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} schüttet dir einen Beutel getrockneter Bohnen vor die Füße. „Für zwei Krüge Honig hat er mir das gegeben. Er sagt, es sind fünf Pfund. Das sind höchstens drei!“","optionen":[{"text":"Zum Händler gehen","weiter":"lager"}]},"lager":{"ort":"dorf","text":"Der Händler sitzt am Feuer, eine Waage mit Messingschalen neben sich. „Beschwerden? Meine Waage lügt nicht, Freund.“","optionen":[{"text":"Die Waage heimlich prüfen","tag":"[Flink]","probe":{"id":"flink","dc":11},"erfolg":{"text":"Unter einer Schale klebt ein Klumpen Wachs mit eingedrückten Kieseln. Klug gemacht.","folgen":{"flag":["beweis"]},"weiter":"stellen"},"misserfolg":{"text":"Er bemerkt deine Hand und zieht die Waage zu sich. „Finger weg.“","folgen":{"flag":["gewarnt"]},"weiter":"stellen"}},{"text":"Ihm in die Augen sehen","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":11},"erfolg":{"text":"Sein Lächeln reicht nicht bis zu den Augen. Er weiß genau, was er getan hat.","folgen":{"flag":["sicher"]},"weiter":"stellen"},"misserfolg":{"text":"Er wirkt wie ein ehrlicher Kerl. Vielleicht hat sich {A} verzählt?","weiter":"stellen"}},{"text":"{B} holen, die oder der kennt sich mit Gewichten aus","weiter":"stellen","ergebnis":"{B} hebt den Bohnensack prüfend an. „Drei Pfund. Großzügig gerechnet.“","folgen":{"flag":["zeuge"],"sym":{"B":1}}}]},"stellen":{"ort":"dorf","text":"Der Händler packt schon langsam zusammen.","optionen":[{"text":"Das Wachs vor allen zeigen","wenn":{"flag":"beweis"},"weiter":"ende_gut","ergebnis":"Ein paar Leute treten näher. Der Händler hebt die Hände. „Schon gut, schon gut.“ Er legt {A} zwei Säcke dazu – und einen dritten, damit niemand weitererzählt, was er gesehen hat."},{"text":"Auf einen fairen Ausgleich bestehen","tag":"[Feilschen]","probe":{"id":"feilschen","dc":13,"mod":{"zeuge":-2,"sicher":-1,"gewarnt":2}},"erfolg":{"text":"Er seufzt theatralisch. „Für den Frieden.“ {A} bekommt den fehlenden Sack – und du einen guten Rat für den nächsten Markt.","weiter":"ende_gut"},"misserfolg":{"text":"„Ich habe nichts falsch gemacht.“ Er spannt an und zieht davon.","weiter":"ende_weg"}},{"text":"Ihn einschüchtern","tag":"[Einschüchtern]","probe":{"id":"einschuechtern","dc":12},"erfolg":{"text":"Er sieht deine Schultern, dann sein Messer, dann wieder deine Schultern. Er zahlt.","folgen":{"dorf":{"stimmung":-1}},"weiter":"ende_gut"},"misserfolg":{"text":"Er lacht dich aus und fährt davon. Einige im Dorf finden, du hast dich lächerlich gemacht.","weiter":"ende_weg"}}]},"ende_gut":{"ort":"dorf","ende":true,"text":"{A} hat bekommen, was {A} zusteht. Und der Händler wird sich gut überlegen, ob er hier noch einmal so handelt.","folgen":{"sym":{"A":4},"merkt":{"A":"{held} hat dafür gesorgt, dass der Händler mich nicht betrügt."},"dorf":{"nahrung":6,"waren":2},"beute":{"stufe":1,"chance":0.35,"text":"Beim Abfahren wirft dir der Händler zähneknirschend etwas aus seinem Karren zu. „Damit wir quitt sind.“"}}},"ende_weg":{"ort":"dorf","ende":true,"text":"Der Karren verschwindet hinter der Biegung. {A} klopft dir trotzdem auf die Schulter. „Du hast es versucht.“","folgen":{"sym":{"A":1}}}}}},{"id":"b_fest","titel":"Wer führt den Erntetanz?","kurz":"Zum Erntefest wollen {A} und {B} beide den ersten Tanz anführen. Das Dorf bittet dich, es zu klären.","schwierigkeit":1,"rollen":{"A":"Tänzer","B":"Tänzer","C":"Wer die alten Lieder kennt"},"def":{"start":"streit","szenen":{"streit":{"ort":"dorf","text":"Der Platz ist mit Laub und Bändern geschmückt. {A} und {B} stehen sich gegenüber. „Ich führe seit drei Jahren!“ – „Eben deshalb ist es Zeit für jemand anderen!“","optionen":[{"text":"Beide erzählen lassen, warum es ihnen wichtig ist","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":10},"erfolg":{"text":"{A} geht es um Stolz. {B} geht es um etwas anderes: Die Eltern von {B} haben den Tanz früher geführt – und sind im letzten Winter gestorben.","folgen":{"flag":["grund"]},"weiter":"alte"},"misserfolg":{"text":"Beide reden gleichzeitig. Du verstehst nur „Tradition“ und „ungerecht“.","weiter":"alte"}},{"text":"{C} nach dem alten Brauch fragen","weiter":"alte"}]},"alte":{"ort":"dorf","text":"{C} lehnt sich zurück. „Früher gab es zwei Tänze. Einen für die Ernte und einen für die, die nicht mehr da sind. Den zweiten hat man irgendwann vergessen.“","optionen":[{"text":"„Dann gibt es dieses Jahr wieder zwei Tänze.“","weiter":"ende_zwei","folgen":{"flag":["zwei"]}},{"text":"{A} soll führen – wer es kann, soll es tun","weiter":"ende_a"},{"text":"{B} soll führen","wenn":{"flag":"grund"},"weiter":"ende_b"}]},"ende_zwei":{"ort":"dorf","ende":true,"text":"Als die Fackeln brennen, führt {A} den Erntetanz – laut, wild, alle lachen. Später, als es still wird, führt {B} den alten Tanz. Niemand spricht dabei. Einige weinen.","folgen":{"sym":{"A":2,"B":4,"C":3},"merkt":{"B":"{held} hat dafür gesorgt, dass wir den alten Tanz für meine Eltern tanzen konnten.","C":"{held} hat einen vergessenen Brauch wieder lebendig gemacht."},"chronik":["brett_fest_zwei","Beim Erntefest gab es auf meinen Vorschlag wieder zwei Tänze – auch einen für die Toten."],"dorf":{"stimmung":5}}},"ende_a":{"ort":"dorf","ende":true,"text":"{A} führt den Tanz, und es wird ein schönes Fest. {B} tanzt mit – aber geht früh nach Hause.","folgen":{"sym":{"A":3,"B":-2},"dorf":{"stimmung":2}}},"ende_b":{"ort":"dorf","ende":true,"text":"{B} führt den Tanz, unsicher erst, dann mit erhobenem Kopf. {A} schmollt eine Weile – und klatscht am Ende doch am lautesten.","folgen":{"sym":{"A":-1,"B":4},"merkt":{"B":"{held} hat mich den Erntetanz führen lassen."},"dorf":{"stimmung":3}}}}}},{"id":"b_woelfe","titel":"Spuren am Pferch","kurz":"Zweimal in einer Woche wurden Schafe von {A} gerissen. {A} will die Wölfe tot sehen, {B} warnt davor.","schwierigkeit":2,"rollen":{"A":"Wer Schafe verloren hat","B":"Wer den Wald kennt","C":"Wer die Fallen stellt"},"def":{"start":"pferch","szenen":{"pferch":{"ort":"dorf","text":"Am Pferch liegen Wollbüschel im Gras. {A} ist außer sich. „Zwei Lämmer! Ich will, dass jemand diese Bestien erledigt.“ {B} schüttelt den Kopf. „Seit oben am Hang gerodet wird, finden die Wölfe kein Wild mehr. Töte das Rudel, und das nächste kommt.“","optionen":[{"text":"Den Spuren in den Wald folgen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":12},"erfolg":{"text":"Die Spuren sind ungleich – ein Tier zieht ein Bein nach. Ein verletzter Wolf jagt, was er kriegen kann.","folgen":{"flag":["lahm"]},"weiter":"wald"},"misserfolg":{"text":"Im Laub verlierst du die Fährte, findest sie aber am Bach wieder.","weiter":"wald"}},{"text":"{B} um Rat fragen","weiter":"wald","ergebnis":"„Such nach dem, was nicht ins Bild passt“, sagt {B}. „Ein gesundes Rudel holt sich keine Lämmer aus einem Pferch am Dorf.“","folgen":{"flag":["rat"]}}]},"wald":{"ort":"wald","text":"Unter einem umgestürzten Baum liegt eine Wölfin. Ihr Hinterlauf steckt noch in einem rostigen Tellereisen. Hinter ihr, im Dunkel, bewegen sich zwei kleine Schatten.","gefahr":true,"optionen":[{"text":"Langsam näher gehen und das Eisen öffnen","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":13},"erfolg":{"text":"Sie knurrt, aber sie lässt dich. Mit einem Ächzen springt das Eisen auf. Die Wölfin humpelt mit ihren Jungen tiefer in den Wald – weg vom Dorf.","folgen":{"flag":["befreit"]},"weiter":"eisen"},"misserfolg":{"text":"Sie schnappt zu. Ihre Zähne streifen deinen Arm. Du weichst zurück, das Eisen bleibt zu.","folgen":{"gefahr":1},"weiter":"entscheidung"}},{"text":"Den Jungen etwas Fleisch hinwerfen und warten","weiter":"entscheidung","ergebnis":"Die Kleinen schlingen. Die Wölfin beobachtet dich, ohne den Blick abzuwenden."},{"text":"Zurück ins Dorf und berichten","weiter":"entscheidung"}]},"entscheidung":{"ort":"wald","text":"Die Wölfin wird so nicht jagen können – außer Lämmer in einem Pferch.","optionen":[{"text":"Sie mit dem Bogen erlösen","tag":"[Bogen]","wenn":{"item":"bogen"},"weiter":"eisen","ergebnis":"Ein Pfeil, schnell und sauber. Die Jungen fliehen ins Unterholz.","folgen":{"flag":["getoetet"]}},{"text":"Ein zweiter Versuch mit dem Eisen – mit Hilfe von {B}","tag":"[Anpacken]","probe":{"id":"anpacken","dc":12,"mod":{"rat":-2}},"erfolg":{"text":"{B} hält einen Mantel vor ihren Kopf, du stemmst das Eisen auf. Sie verschwindet mit den Jungen.","folgen":{"flag":["befreit"],"sym":{"B":3}},"weiter":"eisen"},"misserfolg":{"text":"Das Eisen ist zu verrostet. Ihr geht ohne sie.","weiter":"eisen"}},{"text":"Sie liegen lassen","weiter":"eisen"}]},"eisen":{"ort":"wald","text":"Das Tellereisen trägt ein Zeichen, eingeschlagen ins Metall. Es gehört {C} – und Tellereisen hatte das Dorf eigentlich verboten.","optionen":[{"text":"{C} zur Rede stellen","weiter":"c_rede"},{"text":"Das Eisen verschwinden lassen und schweigen","weiter":"schluss","folgen":{"flag":["geschwiegen"],"merkt":{"C":"{held} hat mein Eisen gefunden – und nichts gesagt."},"sym":{"C":3}}}]},"c_rede":{"ort":"dorf","text":"{C} verschränkt die Arme. „Ja, das ist meins. Die Füchse holen mir die Hühner. Was soll ich denn tun?“","optionen":[{"text":"„Bau einen Zaun. Ich helfe dir dabei.“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":12},"erfolg":{"text":"{C} brummt. „Na gut. Aber du schleppst die Pfähle.“ Am Abend steht ein Zaun – und alle Eisen liegen in der Schmiede.","folgen":{"sym":{"C":2},"flag":["zaun"],"dorf":{"holz":-3}},"weiter":"schluss"},"misserfolg":{"text":"„Spar dir deine Ratschläge.“","folgen":{"sym":{"C":-2}},"weiter":"schluss"}},{"text":"Es vor dem ganzen Dorf ansprechen","weiter":"schluss","ergebnis":"Alle Eisen werden eingesammelt. {C} redet eine Woche lang kein Wort mit dir.","folgen":{"sym":{"C":-5,"B":2},"merkt":{"C":"{held} hat mich wegen der Fallen vor allen angeprangert."}}}]},"schluss":{"ort":"dorf","text":"Zurück am Pferch wartet {A}. „Und? Sind sie tot?“","optionen":[{"text":"„Die Wölfin ist frei und zieht weiter. Es wird keine Lämmer mehr kosten.“","wenn":{"flag":"befreit"},"weiter":"ende","ergebnis":"{A} sieht dich lange an. „Wenn noch ein Lamm fehlt, bist du schuld.“ Aber es fehlt keines mehr.","folgen":{"sym":{"A":1,"B":5},"merkt":{"B":"{held} hat die Wölfin aus dem Eisen befreit. Der Wald vergisst so etwas nicht."},"chronik":["brett_woelfe_frei","Ich habe eine Wölfin aus einem Tellereisen befreit, statt sie zu töten."],"beute":{"stufe":2,"chance":0.5,"text":"Ein paar Tage später legt dir {B} etwas vor die Tür. „Für jemanden, der zuhört, wenn der Wald redet.“"}}},{"text":"„Es ist vorbei. Sie hat nicht mehr gelitten.“","wenn":{"flag":"getoetet"},"weiter":"ende","folgen":{"sym":{"A":4,"B":-1},"merkt":{"A":"{held} hat das Tier erledigt, das meine Lämmer gerissen hat."},"chronik":["brett_woelfe_tot","Ich habe eine verletzte Wölfin erlöst, die Lämmer gerissen hat."]}},{"text":"„Ich konnte nichts tun. Bau den Pferch höher.“","wenn":{"nicht_flag":"befreit"},"weiter":"ende","ergebnis":"{A} flucht – aber am nächsten Morgen schleppt {A} Pfähle für einen höheren Zaun.","folgen":{"sym":{"A":-1},"dorf":{"nahrung":-4}}}]},"ende":{"ort":"dorf","ende":true,"text":"Nachts heulen weit oben im Wald die Wölfe. Diesmal klingt es nicht nach einer Drohung."}}}},{"id":"b_verlobung","titel":"Ein Versprechen im Geheimen","kurz":"{A} und {B} wollen heiraten – doch {C} ist strikt dagegen. {A} bittet dich um Hilfe.","schwierigkeit":2,"rollen":{"A":"Verliebte Person","B":"Verliebte Person","C":"Wer dagegen ist"},"def":{"start":"bitte","szenen":{"bitte":{"ort":"dorf","text":"{A} zieht dich hinter die Scheune. „{B} und ich wollen zum Frühjahr heiraten. Aber {C} hat gedroht, uns das Leben schwer zu machen, wenn wir es wagen. Ich weiß nicht, warum. Kannst du mit {C} reden?“","optionen":[{"text":"„Ich rede mit {C}.“","weiter":"c_haus"},{"text":"„Warum ist {C} so dagegen?“","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":12},"erfolg":{"text":"{A} zögert. „Früher war {C} selbst verlobt. Mit jemandem aus meiner Familie. Es endete schlecht.“","folgen":{"flag":["vergangenheit"]},"weiter":"c_haus"},"misserfolg":{"text":"„Ich weiß es wirklich nicht.“","weiter":"c_haus"}}]},"c_haus":{"ort":"dorf","text":"{C} schält Rüben und sieht nicht auf. „Wenn du wegen der zwei kommst: nein. Aus dieser Familie kommt nur Kummer.“","optionen":[{"text":"„Was ist damals passiert?“","wenn":{"flag":"vergangenheit"},"weiter":"geschichte"},{"text":"„Die beiden lieben sich. Was hast du davon, es zu verhindern?“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":14},"erfolg":{"text":"{C} legt das Messer hin. „Nichts. Vermutlich nichts.“ Ein langes Schweigen. „Lass mich nachdenken.“","folgen":{"flag":["nachdenken"]},"weiter":"entscheidung"},"misserfolg":{"text":"„Raus aus meinem Haus.“","folgen":{"sym":{"C":-2}},"weiter":"entscheidung"}},{"text":"„Wenn du ihnen schadest, bekommst du es mit mir zu tun.“","tag":"[Einschüchtern]","probe":{"id":"einschuechtern","dc":13},"erfolg":{"text":"{C} wird bleich. „Schon gut. Sollen sie doch.“ Aber in den Augen von {C} liegt etwas Bitteres.","folgen":{"flag":["gedroht"],"sym":{"C":-4}},"weiter":"entscheidung"},"misserfolg":{"text":"{C} lacht kalt. „Du bist nicht der Erste, der mir droht.“","folgen":{"sym":{"C":-3}},"weiter":"entscheidung"}}]},"geschichte":{"ort":"dorf","text":"{C} schweigt lange. Dann: „Wir wollten heiraten. Eine Woche vorher war er weg. Hat nicht einmal einen Brief dagelassen. Seine Familie hat so getan, als wäre ich nie gewesen.“","optionen":[{"text":"„Das war nicht {A}. Lass {A} nicht dafür bezahlen.“","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":11},"erfolg":{"text":"{C} wischt sich über die Augen. „Du hast recht. Verdammt, du hast recht.“","folgen":{"flag":["versoehnt"]},"weiter":"entscheidung"},"misserfolg":{"text":"„Das sagst du so leicht.“ Aber {C} wirkt nachdenklich.","folgen":{"flag":["nachdenken"]},"weiter":"entscheidung"}}]},"entscheidung":{"ort":"dorf","text":"Am Abend wartet {A} mit {B} am Dorfbrunnen.","optionen":[{"text":"„{C} wird euch nichts in den Weg legen.“","wenn":{"flag":"versoehnt"},"weiter":"ende_fest","ergebnis":"Zum Fest im Frühjahr kommt {C} als Erste und bringt einen Laib Honigbrot. Niemand fragt, warum {C} dabei die Hand von {A} so lange hält."},{"text":"„{C} denkt darüber nach. Gebt ihr Zeit.“","wenn":{"flag":"nachdenken"},"weiter":"ende_zeit"},{"text":"„{C} hat nachgegeben. Fragt nicht, wie.“","wenn":{"flag":"gedroht"},"weiter":"ende_kalt"},{"text":"„Heiratet trotzdem. Es ist euer Leben.“","weiter":"ende_trotz"}]},"ende_fest":{"ort":"dorf","ende":true,"text":"Die Hochzeit wird das schönste Fest seit Jahren.","folgen":{"sym":{"A":5,"B":5,"C":4},"merkt":{"A":"{held} hat dafür gesorgt, dass {B} und ich heiraten können.","C":"{held} hat mir zugehört, als ich die alte Geschichte erzählt habe."},"chronik":["brett_hochzeit","Ich habe {C} mit der Familie von {A} versöhnt. {A} und {B} heiraten."],"dorf":{"stimmung":6},"beute":{"stufe":2,"chance":0.6,"text":"Nach der Hochzeit drückt dir {A} ein Geschenk in die Hand. „Ohne dich hätten wir das nicht geschafft.“"}}},"ende_zeit":{"ort":"dorf","ende":true,"text":"Ein paar Wochen später sieht man {C} mit {B} reden. Höflich, vorsichtig. Es ist ein Anfang.","folgen":{"sym":{"A":3,"B":2,"C":1},"dorf":{"stimmung":2}}},"ende_kalt":{"ort":"dorf","ende":true,"text":"Die Hochzeit findet statt. {C} bleibt ihr fern und grüßt dich seitdem nicht mehr.","folgen":{"sym":{"A":3,"B":3},"merkt":{"C":"{held} hat mir gedroht, damit diese Hochzeit stattfindet."},"dorf":{"stimmung":1}}},"ende_trotz":{"ort":"dorf","ende":true,"text":"{A} und {B} heiraten still, nur mit ein paar Freunden. {C} schlägt am Tag danach die Tür so laut zu, dass es das ganze Dorf hört.","folgen":{"sym":{"A":2,"B":2,"C":-2}}}}}},{"id":"b_schuld","titel":"Der Schuldeneintreiber","kurz":"Ein Mann aus der Stadt fordert von {A} eine alte Schuld zurück – mit zwei Schlägern im Schlepptau.","schwierigkeit":2,"rollen":{"A":"Wer Schulden hat","B":"Wer helfen könnte"},"def":{"start":"ankunft","szenen":{"ankunft":{"ort":"dorf","text":"Ein Mann in einem guten Mantel steht vor dem Haus von {A}, flankiert von zwei breiten Kerlen mit Knüppeln. „Drei Winter ist es her. Der Zins ist inzwischen höher als die Schuld. Heute wird gezahlt – so oder so.“ {A} steht blass in der Tür.","optionen":[{"text":"Dazwischentreten","weiter":"verhandlung"},{"text":"Erst mit {A} reden","weiter":"a_rede"}]},"a_rede":{"ort":"dorf","text":"{A} flüstert: „Ich habe mir Saatgut geliehen, nach dem Hagel damals. Die Hälfte habe ich längst zurückgezahlt. Aber er sagt, das zählt nicht, weil ich zu spät war.“","optionen":[{"text":"„Hast du einen Beleg für die Zahlung?“","weiter":"verhandlung","ergebnis":"{A} kramt einen zerknitterten Zettel hervor, mit einem halben Siegel. Besser als nichts.","folgen":{"flag":["zettel"]}}]},"verhandlung":{"ort":"dorf","text":"Der Mann mustert dich. „Und du bist? Der Vormund? Dann zahlst du.“","optionen":[{"text":"Den Zettel vorzeigen und rechnen","wenn":{"flag":"zettel"},"tag":"[Feilschen]","probe":{"id":"feilschen","dc":12},"erfolg":{"text":"Du rechnest ihm vor, was gezahlt wurde, mit Zins, ehrlich gerechnet. Er verzieht das Gesicht. „Dann eben der Rest. Aber heute.“","folgen":{"flag":["rest"]},"weiter":"zahlen"},"misserfolg":{"text":"„Ein Fetzen Papier. Nett.“","weiter":"drohung"}},{"text":"Die Zahl in den Schriften nachprüfen","tag":"[Altes Wissen]","probe":{"id":"altes_wissen","dc":13},"erfolg":{"text":"Du kennst das Landrecht: Ein Zins darf die Schuld nicht übersteigen. Er weiß das auch – und weiß, dass du es weißt.","folgen":{"flag":["rest"]},"weiter":"zahlen"},"misserfolg":{"text":"Du redest von Rechten, die du nicht genau kennst. Er grinst.","weiter":"drohung"}},{"text":"„Geh. Hier holst du nichts.“","tag":"[Einschüchtern]","probe":{"id":"einschuechtern","dc":14},"erfolg":{"text":"Einer der Schläger tritt einen Schritt zurück. Der Mann schnaubt. „Wir sprechen uns wieder.“ Aber er geht.","folgen":{"flag":["vertrieben"]},"weiter":"ende_weg"},"misserfolg":{"text":"Der größere der beiden Kerle hebt den Knüppel.","weiter":"kampf"}}]},"drohung":{"ort":"dorf","text":"„Zahlen oder ich nehme mir, was es wert ist.“ Er sieht zur Ziege von {A}, dann zum Werkzeug an der Wand.","optionen":[{"text":"Leute aus dem Dorf zusammenrufen","weiter":"zahlen","ergebnis":"Nach und nach kommen Leute aus den Häusern. Gegen ein halbes Dorf mögen zwei Knüppel nicht so viel. Der Mann lässt mit sich reden.","folgen":{"flag":["rest"],"sym":{"B":2}}},{"text":"Sich ihm in den Weg stellen","weiter":"kampf"}]},"kampf":{"ort":"dorf","gefahr":true,"text":"Der erste Schlag kommt schneller als erwartet.","optionen":[{"text":"Zurückschlagen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":13},"erfolg":{"text":"Du duckst dich, packst den Knüppel und stößt den Kerl in den Matsch. Der zweite überlegt es sich anders.","folgen":{"flag":["vertrieben"]},"weiter":"ende_weg"},"misserfolg":{"text":"Ein Treffer an der Schulter wirft dich zu Boden. {B} zieht dich weg, bevor der zweite Schlag kommt.","folgen":{"gefahr":2,"sym":{"B":2}},"weiter":"zahlen"}},{"text":"Ausweichen und den Mann selbst packen","tag":"[Flink]","probe":{"id":"flink","dc":13},"erfolg":{"text":"Plötzlich hast du den Mann im Mantel am Kragen. Seine Schläger erstarren. „Schon gut! Wir gehen!“","folgen":{"flag":["vertrieben"]},"weiter":"ende_weg"},"misserfolg":{"text":"Du stolperst, der Knüppel trifft dich am Rücken.","folgen":{"gefahr":1},"weiter":"zahlen"}}]},"zahlen":{"ort":"dorf","text":"Am Ende geht es nur noch um den Rest der Schuld. Das Dorf könnte ihn gemeinsam aufbringen.","optionen":[{"text":"Aus den Vorräten des Dorfes zahlen","weiter":"ende_bezahlt","folgen":{"dorf":{"waren":-4,"nahrung":-6}}},{"text":"{A} soll selbst zahlen, wie es geht","weiter":"ende_selbst"}]},"ende_bezahlt":{"ort":"dorf","ende":true,"text":"Der Mann quittiert mit einem Siegel, diesmal vollständig. {A} hat Tränen in den Augen. „Ich zahle es dem Dorf zurück. Jeden Krümel.“","folgen":{"sym":{"A":6,"B":2},"merkt":{"A":"{held} hat dafür gesorgt, dass das Dorf meine Schuld getragen hat."},"chronik":["brett_schuld_dorf","Das Dorf hat die alte Schuld von {A} gemeinsam beglichen."],"dorf":{"stimmung":3}}},"ende_selbst":{"ort":"dorf","ende":true,"text":"{A} gibt die beiden besten Werkzeuge her. Die Schuld ist getilgt, aber die Arbeit wird jetzt schwerer.","folgen":{"sym":{"A":2},"dorf":{"waren":-2}}},"ende_weg":{"ort":"dorf","ende":true,"text":"Der Mann und seine Schläger ziehen ab. {A} fällt dir um den Hals. Ob sie wiederkommen, wird sich zeigen.","folgen":{"sym":{"A":5},"merkt":{"A":"{held} hat den Schuldeneintreiber vertrieben."},"chronik":["brett_schuld_weg","Ich habe einen Schuldeneintreiber aus der Stadt aus dem Dorf gejagt."],"beute":{"stufe":2,"chance":0.4,"text":"Einer der Schläger hat im Matsch etwas verloren."}}}}}},{"id":"b_fremde","titel":"Die Fremden am Fluss","kurz":"Am Flussufer haben Fremde ein Lager aufgeschlagen. {A} will sie verjagen, {B} will ihnen helfen.","schwierigkeit":2,"rollen":{"A":"Wer Angst hat","B":"Wer helfen will"},"def":{"start":"dorf","szenen":{"dorf":{"ort":"dorf","text":"„Sechs Leute, zwei Karren, ein Feuer“, sagt {A}. „Wer weiß, was die wollen. Gestern hat jemand Rüben vom Feld genommen.“ {B} schüttelt den Kopf. „Es sind Kinder dabei. Ich hab sie gesehen.“","optionen":[{"text":"Zum Lager gehen","weiter":"weg"}]},"weg":{"ort":"wald","text":"Der Pfad führt am Fluss entlang. Rauch steigt zwischen den Erlen auf.","reise":{"minuten":1,"weiter":"lager"}},"lager":{"ort":"feuer","text":"Am Feuer sitzen müde Gesichter. Ein grauhaariger Mann steht auf. „Wir wollen keinen Ärger. Unser Dorf liegt drei Tage flussaufwärts. Lag. Es ist niedergebrannt. Wir suchen nur einen Ort für den Winter.“","optionen":[{"text":"Prüfen, ob er die Wahrheit sagt","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":12},"erfolg":{"text":"Er sagt die Wahrheit. Und er verschweigt etwas: Einer von ihnen ist krank und liegt im Karren.","folgen":{"flag":["krank"]},"weiter":"karren"},"misserfolg":{"text":"Du kannst ihn nicht lesen. Müde Menschen sehen alle gleich aus.","weiter":"entscheidung"}},{"text":"„Wer hat die Rüben genommen?“","weiter":"entscheidung","ergebnis":"Ein Junge senkt den Kopf. Der Alte legt ihm die Hand auf die Schulter. „Er hatte Hunger. Wir arbeiten es ab.“","folgen":{"flag":["ehrlich"]}}]},"karren":{"ort":"feuer","text":"Im Karren liegt eine Frau mit glühender Stirn. Kein Ausschlag, keine Flecken – aber hohes Fieber.","optionen":[{"text":"Sie untersuchen","tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":12},"erfolg":{"text":"Eine entzündete Wunde am Bein, nichts Ansteckendes. Mit Ruhe und sauberem Verband wird sie es schaffen.","folgen":{"flag":["nicht_ansteckend"]},"weiter":"entscheidung"},"misserfolg":{"text":"Du weißt nicht, was sie hat. Und das macht dir Sorgen.","weiter":"entscheidung"}}]},"entscheidung":{"ort":"feuer","text":"Die Fremden sehen dich an. Was du jetzt sagst, wird im Dorf Gewicht haben.","optionen":[{"text":"„Kommt mit. Für die Arbeit eurer Hände gibt es Brot und ein Dach.“","weiter":"dorf_rueck","folgen":{"flag":["aufgenommen"]}},{"text":"„Ihr könnt bleiben, wo ihr seid. Wir bringen euch, was wir entbehren können.“","weiter":"dorf_rueck","folgen":{"flag":["versorgt"],"dorf":{"nahrung":-8}}},{"text":"„Zieht weiter. Für euch ist hier kein Platz.“","weiter":"dorf_rueck","folgen":{"flag":["vertrieben"]}}]},"dorf_rueck":{"ort":"dorf","text":"Zurück im Dorf warten {A} und {B} – und noch ein paar andere.","optionen":[{"text":"Die Aufnahme verteidigen","wenn":{"flag":"aufgenommen"},"tag":"[Überreden]","probe":{"id":"ueberreden","dc":12,"mod":{"nicht_ansteckend":-3,"ehrlich":-1}},"erfolg":{"text":"„Es ist keine Seuche, und sie wollen arbeiten“, sagst du. {A} murrt, nickt dann aber. Die meisten Fremden ziehen im Frühjahr weiter – eine Familie bleibt.","folgen":{"zuzug":true,"sym":{"B":4,"A":1},"dorf":{"stimmung":1,"nahrung":-5}},"weiter":"ende_auf"},"misserfolg":{"text":"Die Stimmung kippt. Am Ende dürfen die Fremden nur bis zum ersten Schnee in der alten Scheune schlafen.","folgen":{"sym":{"B":2,"A":-1},"dorf":{"stimmung":-2,"nahrung":-4}},"weiter":"ende_halb"}},{"text":"Erzählen, dass das Dorf ihnen etwas abgibt","wenn":{"flag":"versorgt"},"weiter":"ende_halb","folgen":{"sym":{"B":3}}},{"text":"Berichten, dass sie weiterziehen","wenn":{"flag":"vertrieben"},"weiter":"ende_weg","folgen":{"sym":{"A":3,"B":-4},"merkt":{"B":"{held} hat die Fremden am Fluss in den Winter geschickt."}}}]},"ende_auf":{"ort":"dorf","ende":true,"text":"Eine fremde Familie hat ein neues Zuhause. Das Dorf ist ein Stück größer geworden – und ein Stück wärmer.","folgen":{"merkt":{"B":"{held} hat die Fremden ins Dorf geholt. Ich bin stolz auf uns."},"chronik":["brett_fremde_auf","Ich habe die Fremden vom Fluss ins Dorf geholt."]}},"ende_halb":{"ort":"dorf","ende":true,"text":"Die Fremden überwintern am Rand des Dorfes. Im Frühjahr sind sie fort. Ein geschnitzter Vogel bleibt auf deiner Türschwelle zurück.","folgen":{"chronik":["brett_fremde_halb","Das Dorf hat den Fremden vom Fluss über den Winter geholfen."]}},"ende_weg":{"ort":"dorf","ende":true,"text":"Am nächsten Morgen ist das Lager am Fluss leer. Nur die Feuerstelle raucht noch.","folgen":{"chronik":["brett_fremde_weg","Ich habe die Fremden vom Fluss weggeschickt."]}}}}},{"id":"b_nebel","titel":"Vermisst im Nebel","kurz":"{A} ist gestern zum Holzsammeln in den Wald gegangen und nicht zurückgekehrt. {B} hat Angst um {A}.","schwierigkeit":2,"rollen":{"A":"Vermisste Person","B":"Wer sich sorgt"},"def":{"start":"sorge","szenen":{"sorge":{"ort":"dorf","text":"{B} hat nicht geschlafen. „{A} wollte nur Reisig holen, drüben beim Moor. Dann kam der Nebel. Bitte, such mit mir.“","optionen":[{"text":"Sofort losgehen","weiter":"moor"},{"text":"Laterne und Seil mitnehmen","wenn":{"item":"laterne"},"weiter":"moor","folgen":{"flag":["licht"]},"ergebnis":"Die Laterne schneidet ein kleines, warmes Loch in den Nebel."}]},"moor":{"ort":"wald","text":"Der Nebel hängt wie nasse Wolle zwischen den Birken. Irgendwo gluckst Wasser. Der Pfad teilt sich.","optionen":[{"text":"Nach Spuren suchen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":12,"mod":{"licht":-2}},"erfolg":{"text":"Abgebrochene Zweige, ein verlorenes Reisigbündel – nach links, zum Moor hin.","weiter":"rufen"},"misserfolg":{"text":"Alles sieht gleich aus. Ihr geht nach rechts – und landet nach einer Stunde wieder an der Gabelung.","folgen":{"flag":["verirrt"]},"weiter":"rufen"}},{"text":"Laut rufen und lauschen","weiter":"rufen"}]},"rufen":{"ort":"wald","text":"Ihr ruft. Lange nichts. Dann, ganz schwach, eine Antwort – von irgendwo vor euch, wo der Boden schwarz und weich wird.","optionen":[{"text":"Vorsichtig weitergehen","tag":"[Flink]","probe":{"id":"flink","dc":12},"erfolg":{"text":"Von Grasbult zu Grasbult tastest du dich vor.","weiter":"fund"},"misserfolg":{"text":"Du trittst daneben und versinkst bis zur Hüfte. {B} zieht dich heraus, nass und zitternd.","folgen":{"gefahr":1},"weiter":"fund"}},{"text":"Äste auslegen und einen sicheren Pfad bauen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":11},"erfolg":{"text":"Langsam, aber sicher wächst ein Weg aus Ästen über das Moor.","folgen":{"flag":["pfad"]},"weiter":"fund"},"misserfolg":{"text":"Die Äste versinken. Ihr müsst es doch so versuchen.","weiter":"fund"}}]},"fund":{"ort":"wald","text":"{A} sitzt auf einem umgestürzten Stamm, ein Bein seltsam abgewinkelt, die Lippen blau vor Kälte. „Ich dachte, keiner kommt mehr.“","optionen":[{"text":"Das Bein schienen","tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":12},"erfolg":{"text":"Du richtest das Bein und schienst es mit zwei Ästen. {A} beißt in einen Lederriemen und schreit nicht.","folgen":{"flag":["geschient"]},"weiter":"heim"},"misserfolg":{"text":"Du bindest es, so gut es geht. Jeder Schritt wird eine Qual.","weiter":"heim"}},{"text":"{A} einfach tragen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":13,"mod":{"pfad":-3}},"erfolg":{"text":"Du nimmst {A} auf den Rücken. Es ist weit, aber ihr schafft es.","folgen":{"flag":["getragen"]},"weiter":"heim"},"misserfolg":{"text":"Nach hundert Schritten brecht ihr fast zusammen. {B} läuft ins Dorf und holt Hilfe.","weiter":"heim"}}]},"heim":{"ort":"dorf","ende":true,"text":"Im Dorf wird {A} in Decken gewickelt. Das Bein wird heilen. {B} lässt deine Hand nicht los.","folgen":{"sym":{"A":6,"B":5},"merkt":{"A":"{held} hat mich aus dem Nebelmoor geholt. Ich verdanke dir mein Leben.","B":"{held} hat mit mir nach {A} gesucht, als sonst keiner ging."},"chronik":["brett_nebel","Ich habe {A} verletzt im Nebelmoor gefunden und ins Dorf zurückgebracht."],"dorf":{"stimmung":2},"beute":{"stufe":2,"chance":0.4,"text":"Als {A} wieder laufen kann, bringt {A} dir etwas vorbei. „Für den, der nicht aufgegeben hat.“"}}}}}},{"id":"b_eber","titel":"Der alte Eber","kurz":"Ein riesiger Keiler verwüstet nachts die Felder. Die Jäger wollen ihn töten – {A} sagt, mit dem Tier stimmt etwas nicht.","schwierigkeit":3,"rollen":{"A":"Wer den Wald kennt","B":"Wer ihn töten will"},"def":{"start":"feld","szenen":{"feld":{"ort":"dorf","text":"Das Feld sieht aus wie gepflügt, nur kreuz und quer. Tiefe Hufabdrücke, größer als eine Hand. {B} prüft die Speerspitze. „Heute Nacht hole ich ihn mir.“ {A} hält dich am Ärmel zurück. „Wildschweine meiden Dörfer. Er nicht. Irgendwas treibt ihn.“","optionen":[{"text":"Mit {A} den Spuren folgen","weiter":"wald"},{"text":"Mit {B} auf der Lauer liegen","weiter":"lauer"}]},"lauer":{"ort":"feld","text":"Mitternacht. Der Mond hinter Wolken. Dann bricht etwas durch die Hecke – ein Keiler, so groß wie ein Kalb, ein Hauer abgebrochen. Er schnaubt, schwankt, wühlt.","gefahr":true,"optionen":[{"text":"Genau hinsehen","tag":"[Sinne]","probe":{"id":"spuren","dc":13},"erfolg":{"text":"In seiner Flanke steckt etwas Dunkles, Metallisches. Die Wunde eitert. Er hat Schmerzen – und Hunger.","folgen":{"flag":["wunde"]},"weiter":"lauer_wahl"},"misserfolg":{"text":"Ein riesiger Schatten. Mehr siehst du nicht.","weiter":"lauer_wahl"}}]},"lauer_wahl":{"ort":"feld","gefahr":true,"text":"{B} hebt den Speer.","optionen":[{"text":"{B} den Wurf lassen","weiter":"kampf"},{"text":"{B} zurückhalten","tag":"[Überreden]","probe":{"id":"ueberreden","dc":13,"mod":{"wunde":-3}},"erfolg":{"text":"{B} senkt zögernd den Speer. Der Keiler trollt sich in den Wald.","folgen":{"sym":{"B":-1}},"weiter":"wald"},"misserfolg":{"text":"„Aus dem Weg!“ {B} wirft.","weiter":"kampf"}}]},"kampf":{"ort":"feld","gefahr":true,"text":"Der Speer streift ihn nur. Brüllend wendet sich der Keiler – und kommt direkt auf euch zu.","optionen":[{"text":"Ihn mit dem Speer abfangen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":15},"erfolg":{"text":"Du stemmst den Schaft in den Boden. Der Keiler läuft hinein. Es ist schnell vorbei.","folgen":{"flag":["erlegt"]},"weiter":"nach_kampf"},"misserfolg":{"text":"Der Aufprall schleudert dich durch die Luft. Als du aufstehst, liegt der Keiler still – {B} hat den zweiten Speer geworfen.","folgen":{"flag":["erlegt"],"gefahr":2},"weiter":"nach_kampf"}},{"text":"Zur Seite springen und ihn ins Leere laufen lassen","tag":"[Flink]","probe":{"id":"flink","dc":14},"erfolg":{"text":"Er donnert an dir vorbei, durch den Zaun, in den Wald. Fort.","weiter":"wald"},"misserfolg":{"text":"Ein Hauer reißt dir das Bein auf, bevor er im Dunkel verschwindet.","folgen":{"gefahr":2},"weiter":"wald"}}]},"nach_kampf":{"ort":"feld","text":"Im Fackelschein seht ihr es: In der Flanke des Tieres steckt eine eiserne Armbrustspitze, schwarz vom Eiter. Kein Jäger aus dem Dorf benutzt solche Bolzen.","optionen":[{"text":"Die Spitze an dich nehmen","weiter":"ende_erlegt","folgen":{"flag":["spitze"]}}]},"wald":{"ort":"wald","text":"Die Fährte führt tief in den Wald, an Wurzeln vorbei, die der Keiler zerfetzt hat. An einer Suhle findet ihr ihn liegend, keuchend. Er sieht euch – und steht nicht auf.","optionen":[{"text":"Langsam näher gehen","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":14},"erfolg":{"text":"Er grunzt warnend, bleibt aber liegen. In seiner Flanke steckt eine Armbrustspitze, tief im entzündeten Fleisch.","folgen":{"flag":["nah"]},"weiter":"heilen"},"misserfolg":{"text":"Er rappelt sich hoch und stürmt auf euch zu. {A} reißt dich hinter eine Eiche. Der Keiler bricht zusammen, ein paar Schritte vor euch.","folgen":{"gefahr":1},"weiter":"heilen"}},{"text":"Ihn aus der Ferne erlösen","tag":"[Bogen]","wenn":{"item":"bogen"},"weiter":"ende_erlegt","ergebnis":"Ein Pfeil. Er hebt den Kopf, legt ihn wieder hin. Als ihr näher kommt, seht ihr die Armbrustspitze in seiner Flanke.","folgen":{"flag":["erlegt","spitze"]}}]},"heilen":{"ort":"wald","text":"{A} kniet sich neben dich. „Wenn wir das Eisen herausbekommen, hat er eine Chance. Er wird uns nicht danken – aber er wird nicht mehr ins Dorf kommen.“","optionen":[{"text":"Die Spitze herausschneiden","tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":15,"mod":{"nah":-2}},"erfolg":{"text":"Ein schneller Schnitt, ein Ruck, ein Schwall. Der Keiler brüllt – und bleibt liegen. {A} streut gekaute Schafgarbe in die Wunde. Am Morgen ist die Suhle leer.","folgen":{"flag":["geheilt","spitze"]},"weiter":"ende_geheilt"},"misserfolg":{"text":"Die Spitze sitzt zu tief. Er wehrt sich, verletzt dich am Arm. {A} erlöst ihn schließlich mit dem Messer.","folgen":{"flag":["erlegt","spitze"],"gefahr":1},"weiter":"ende_erlegt"}},{"text":"Ihn erlösen","weiter":"ende_erlegt","folgen":{"flag":["erlegt","spitze"]}}]},"ende_geheilt":{"ort":"dorf","ende":true,"text":"Der Keiler kommt nie wieder. Manchmal, sagt {A}, sieht man im Frühjahr am Moor einen großen Schatten mit nur einem Hauer – und eine Rotte Frischlinge hinter ihm. Die eiserne Spitze aber gibt Rätsel auf: Wer jagt hier mit Armbrüsten?","folgen":{"sym":{"A":6,"B":-2},"merkt":{"A":"{held} hat dem alten Keiler das Eisen herausgeschnitten. So etwas tut kaum jemand.","B":"{held} hat mir die Beute weggenommen. Ich weiß nicht, ob das mutig war oder dumm."},"chronik":["brett_eber_geheilt","Ich habe einen verwundeten Keiler im Wald geheilt, statt ihn zu töten. In ihm steckte eine fremde Armbrustspitze."],"journal":["armbrust","Fremde Armbrüste","Im Wald um das Dorf jagt jemand mit eisernen Armbrustbolzen. Kein Jäger aus dem Dorf benutzt so etwas."],"beute":{"stufe":3,"chance":0.5,"text":"An der leeren Suhle liegt etwas im Schlamm, das nicht dorthin gehört – verloren von demjenigen, der den Keiler angeschossen hat."}}},"ende_erlegt":{"ort":"dorf","ende":true,"text":"Der Keiler wird zerlegt, das Dorf isst eine Woche lang Fleisch. {B} lässt sich feiern. Du aber drehst die schwarze Armbrustspitze zwischen den Fingern: Wer jagt hier mit so etwas?","folgen":{"sym":{"B":4,"A":-1},"merkt":{"B":"{held} war dabei, als wir den großen Keiler erlegt haben."},"chronik":["brett_eber_erlegt","Wir haben den alten Keiler erlegt, der die Felder verwüstet hat. In ihm steckte eine fremde Armbrustspitze."],"journal":["armbrust","Fremde Armbrüste","Im Wald um das Dorf jagt jemand mit eisernen Armbrustbolzen. Kein Jäger aus dem Dorf benutzt so etwas."],"dorf":{"nahrung":25,"waren":2},"beute":{"stufe":2,"chance":0.5,"text":"{B} gibt dir einen Anteil – „wer mitjagt, teilt“."}}}}}},{"id":"b_zoll","titel":"Der Zoll am Steg","kurz":"Bewaffnete eines fremden Herrn haben den Steg über den Fluss besetzt und verlangen Zoll von jedem, auch von {A}.","schwierigkeit":3,"rollen":{"A":"Wer über den Fluss muss","B":"Wer kämpfen will","C":"Wer verhandeln will"},"def":{"start":"bericht","szenen":{"bericht":{"ort":"dorf","text":"{A} kommt mit leerem Karren zurück. „Sie wollten ein Drittel von allem. Im Namen eines Herrn von Kaltenbrunn, von dem ich nie gehört habe.“ {B} ballt die Fäuste. „Fünf Mann? Die jagen wir weg.“ {C} schüttelt den Kopf. „Und morgen kommen fünfzig.“","optionen":[{"text":"Selbst zum Steg gehen","weiter":"weg"}]},"weg":{"ort":"wald","text":"Der Weg zum Steg führt durch Erlen und Schilf. Schon von weitem hörst du Stimmen und das Klirren von Rüstungen.","reise":{"minuten":1,"weiter":"steg"}},"steg":{"ort":"wald","text":"Fünf Männer in zusammengewürfelten Rüstungen. Ihr Anführer, ein Mann mit Narbe am Kinn, lehnt an einem Pfosten. „Der Herr von Kaltenbrunn schützt diesen Steg. Schutz kostet.“","optionen":[{"text":"Ihr Abzeichen und ihre Ausrüstung mustern","tag":"[Sinne]","probe":{"id":"spuren","dc":13},"erfolg":{"text":"Die Wappen sind frisch aufgemalt, die Rüstungen von verschiedenen Schlachtfeldern. Keine Truppe eines Herrn – Söldner, die sich selbst einen Herrn ausgedacht haben.","folgen":{"flag":["falsch"]},"weiter":"wahl"},"misserfolg":{"text":"Bewaffnete Männer. Mehr musst du nicht wissen.","weiter":"wahl"}},{"text":"Nach dem Herrn von Kaltenbrunn fragen","tag":"[Altes Wissen]","probe":{"id":"altes_wissen","dc":14},"erfolg":{"text":"Kaltenbrunn ist eine Ruine, seit zwanzig Jahren. Du sagst es nicht laut – noch nicht.","folgen":{"flag":["falsch","ruine"]},"weiter":"wahl"},"misserfolg":{"text":"Der Name sagt dir nichts.","weiter":"wahl"}}]},"wahl":{"ort":"wald","text":"Der Narbige wartet. Hinter dir rauscht der Fluss.","optionen":[{"text":"„Kaltenbrunn ist seit zwanzig Jahren eine Ruine. Wessen Zoll ist das wirklich?“","wenn":{"flag":"ruine"},"tag":"[Einschüchtern]","probe":{"id":"einschuechtern","dc":13},"erfolg":{"text":"Einer der Männer lacht nervös. Der Narbige sieht dich lange an. „Kluger Kopf. Sag, was du willst.“","folgen":{"flag":["durchschaut"]},"weiter":"angebot"},"misserfolg":{"text":"„Dann eben in meinem Namen.“ Er zieht sein Schwert eine Handbreit.","weiter":"angebot"}},{"text":"Verhandeln","tag":"[Feilschen]","probe":{"id":"feilschen","dc":15,"mod":{"falsch":-2}},"erfolg":{"text":"Am Ende einigt ihr euch auf einen kleinen Wegzoll – einmal im Monat, nicht von jedem Karren.","folgen":{"flag":["einigung"]},"weiter":"ende_einigung"},"misserfolg":{"text":"„Ein Drittel. Oder ihr geht schwimmen.“","weiter":"angebot"}},{"text":"Mit {B} und ein paar anderen zurückkommen und angreifen","weiter":"kampf"}]},"angebot":{"ort":"wald","text":"„Hör zu“, sagt der Narbige leiser. „Wir haben im Krieg gedient, für einen Herrn, der uns nie bezahlt hat. Wir wollen nicht rauben. Wir wollen nur überleben.“","optionen":[{"text":"„Dann schützt den Steg wirklich – für Brot und Unterkunft.“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":14,"mod":{"durchschaut":-3}},"erfolg":{"text":"Er streckt dir die Hand hin. „Für Brot und ein Dach halten wir die Räuber vom Hohlweg fern. Abgemacht.“","folgen":{"flag":["waechter"]},"weiter":"ende_waechter"},"misserfolg":{"text":"„Brot? Wir sind keine Bettler.“","weiter":"kampf"}},{"text":"„Verschwindet, bevor das ganze Tal hier steht.“","tag":"[Einschüchtern]","probe":{"id":"einschuechtern","dc":14,"mod":{"durchschaut":-2}},"erfolg":{"text":"Er spuckt aus, aber er gibt seinen Männern ein Zeichen. Am Abend ist der Steg frei.","weiter":"ende_frei"},"misserfolg":{"text":"„Mutig. Und dumm.“","weiter":"kampf"}}]},"kampf":{"ort":"wald","gefahr":true,"text":"Mit {B} und vier anderen aus dem Dorf stehst du am Steg. Die Söldner bilden eine Reihe.","optionen":[{"text":"Angreifen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":15},"erfolg":{"text":"Es ist schnell und hässlich. Zwei Söldner springen in den Fluss, die anderen fliehen. Niemand aus dem Dorf stirbt.","folgen":{"sym":{"B":4}},"weiter":"ende_frei"},"misserfolg":{"text":"Die Söldner wissen, was sie tun. Ihr müsst euch zurückziehen, {B} blutet am Kopf. Am nächsten Morgen sind sie trotzdem fort – zu viel Ärger für zu wenig Beute.","folgen":{"gefahr":2,"sym":{"B":2},"dorf":{"stimmung":-3}},"weiter":"ende_frei"}},{"text":"Einen Hinterhalt im Schilf legen","tag":"[Flink]","probe":{"id":"flink","dc":14},"erfolg":{"text":"Aus dem Schilf heraus überrascht ihr sie. Sie geben auf, bevor jemand ernsthaft verletzt wird.","weiter":"ende_frei"},"misserfolg":{"text":"Einer bemerkt euch. Es kommt doch zum Kampf.","folgen":{"gefahr":1},"weiter":"ende_frei"}}]},"ende_einigung":{"ort":"dorf","ende":true,"text":"Der Steg bleibt offen, gegen einen kleinen Zoll. Nicht jeder im Dorf ist zufrieden – aber niemand musste bluten.","folgen":{"sym":{"C":4,"B":-2,"A":2},"chronik":["brett_zoll_einigung","Ich habe mit den Söldnern am Steg einen kleinen Zoll ausgehandelt."],"dorf":{"waren":-2}}},"ende_waechter":{"ort":"dorf","ende":true,"text":"Fünf Söldner bewachen jetzt den Steg – für das Dorf. Ihr Anführer nennt sich Harrek und grüßt dich jedes Mal mit einem knappen Nicken.","folgen":{"sym":{"C":5,"A":3},"merkt":{"C":"{held} hat aus Wegelagerern Wächter gemacht. Das hätte ich nie gedacht."},"chronik":["brett_zoll_waechter","Die Söldner am Steg bewachen jetzt für Brot und Unterkunft den Weg für unser Dorf."],"journal":["harrek","Harrek vom Steg","Harrek und vier Söldner, ehemals Soldaten ohne Sold, bewachen jetzt den Steg für unser Dorf."],"dorf":{"nahrung":-10,"stimmung":2},"beute":{"stufe":3,"chance":0.5,"text":"Harrek gibt dir etwas aus seinem Kriegsgepäck. „Ich brauche es nicht mehr. Du vielleicht.“"}}},"ende_frei":{"ort":"dorf","ende":true,"text":"Der Steg ist wieder frei. Abends erzählt man sich am Feuer, wie es war – jedes Mal ein bisschen heldenhafter.","folgen":{"sym":{"B":3,"A":3},"merkt":{"B":"{held} hat mit mir den Steg freigekämpft."},"chronik":["brett_zoll_frei","Wir haben die falschen Zöllner vom Steg vertrieben."],"dorf":{"stimmung":3},"beute":{"stufe":2,"chance":0.6,"text":"Am Steg haben die Söldner in der Eile etwas zurückgelassen."}}}}}},{"id":"b_spitzel","titel":"Wer verrät das Dorf?","kurz":"Räuber wussten genau, wann der Vorratswagen unterwegs war. Jemand im Dorf muss geredet haben – {A}, {B} oder {C}.","schwierigkeit":3,"rollen":{"A":"Verdächtige Person","B":"Verdächtige Person","C":"Verdächtige Person"},"def":{"start":"ueberfall","szenen":{"ueberfall":{"ort":"dorf","text":"Der Vorratswagen kam leer zurück. Die Räuber haben gewartet, genau an der Stelle, an genau dem Tag. Nur drei Leute wussten davon: {A}, {B} und {C}. Das Dorf erwartet, dass du herausfindest, wer geredet hat.","optionen":[{"text":"Mit {A} reden","weiter":"a"},{"text":"Mit {B} reden","weiter":"b"},{"text":"Mit {C} reden","weiter":"c"}]},"a":{"ort":"dorf","text":"{A} ist wütend. „Ich? Ich habe die halbe Ladung selbst gepackt! Frag lieber, wer neuerdings so viel Zeit im Gasthaus in Furtenau verbringt.“","optionen":[{"text":"Prüfen, ob {A} ehrlich ist","tag":"[Menschenkenntnis]","wenn":{"nicht_flag":"a_geprueft"},"probe":{"id":"menschenkenntnis","dc":13},"erfolg":{"text":"Die Wut ist echt. {A} hat nichts zu verbergen – aber {A} deutet auf jemanden.","folgen":{"flag":["a_geprueft","a_unschuldig"]},"weiter":"a"},"misserfolg":{"text":"Du kannst {A} nicht einschätzen.","folgen":{"flag":["a_geprueft"]},"weiter":"a"}},{"text":"„Wer war in Furtenau?“","weiter":"ueberblick","ergebnis":"„{B}. Dreimal in diesem Monat. Angeblich wegen einer Tante.“","folgen":{"flag":["furtenau"]}},{"text":"Zurück","weiter":"ueberblick"}]},"b":{"ort":"dorf","text":"{B} weicht deinem Blick aus. „Ja, ich war in Furtenau. Meine Tante ist krank. Ist das verboten?“","optionen":[{"text":"Nach der Tante fragen","tag":"[Menschenkenntnis]","wenn":{"nicht_flag":"b_geprueft"},"probe":{"id":"menschenkenntnis","dc":14},"erfolg":{"text":"Bei der Tante zittert die Stimme nicht. Aber als du nach dem Gasthaus fragst, schon. {B} verheimlicht etwas – nur vielleicht nicht das, was du denkst.","folgen":{"flag":["b_geprueft","b_geheimnis"]},"weiter":"b"},"misserfolg":{"text":"{B} wirkt nervös. Aber wer wäre das nicht?","folgen":{"flag":["b_geprueft"]},"weiter":"b"}},{"text":"„Was ist im Gasthaus passiert?“","wenn":{"flag":"b_geheimnis"},"weiter":"ueberblick","ergebnis":"{B} wird rot. „Ich … habe gespielt. Würfel. Und verloren. Mehr als ich habe. Aber ich habe niemandem vom Wagen erzählt! Ich schwöre!“","folgen":{"flag":["spielschulden"]}},{"text":"Zurück","weiter":"ueberblick"}]},"c":{"ort":"dorf","text":"{C} ist die Ruhe selbst. „Schlimme Sache. Ich helfe gern, wo ich kann. Brauchst du etwas?“","optionen":[{"text":"Die Hütte von {C} durchsuchen, solange {C} auf dem Feld ist","tag":"[Flink]","wenn":{"nicht_flag":"c_gesucht"},"probe":{"id":"flink","dc":14},"erfolg":{"text":"Unter einer losen Diele: ein Beutel mit fremden Münzen. Mehr, als {C} in einem Jahr verdient.","folgen":{"flag":["c_gesucht","muenzen"]},"weiter":"c"},"misserfolg":{"text":"Du findest nichts – und {C} kommt früher zurück, als dir lieb ist. {C} sagt nichts, aber sieht dich lange an.","folgen":{"flag":["c_gesucht","c_gewarnt"]},"weiter":"c"}},{"text":"{C} unterwegs beobachten","tag":"[Spuren lesen]","wenn":{"nicht_flag":"c_beobachtet"},"probe":{"id":"spuren","dc":13,"mod":{"c_gewarnt":3}},"erfolg":{"text":"In der Dämmerung schleicht {C} zum alten Hohlweg und legt etwas unter einen Stein. Eine Nachricht.","folgen":{"flag":["c_beobachtet","nachricht"]},"weiter":"c"},"misserfolg":{"text":"{C} geht nur zum Feld und zurück. Wenn {C} etwas weiß, ist {C} vorsichtig.","folgen":{"flag":["c_beobachtet"]},"weiter":"c"}},{"text":"Zurück","weiter":"ueberblick"}]},"ueberblick":{"ort":"dorf","text":"Das Dorf wartet auf eine Antwort. Du kannst weiter nachforschen oder jemanden benennen.","optionen":[{"text":"Weiter mit {A} reden","weiter":"a"},{"text":"Weiter mit {B} reden","weiter":"b"},{"text":"Weiter mit {C} reden","weiter":"c"},{"text":"Jemanden benennen","weiter":"urteil"}]},"urteil":{"ort":"dorf","text":"Auf dem Platz stehen alle drei. Die Leute schweigen.","optionen":[{"text":"{C} mit den Münzen und der Nachricht konfrontieren","wenn":{"flag":"nachricht"},"weiter":"c_gestaendnis"},{"text":"{C} mit den Münzen konfrontieren","wenn":{"flag":"muenzen","nicht_flag":"nachricht"},"tag":"[Einschüchtern]","probe":{"id":"einschuechtern","dc":14},"erfolg":{"text":"{C} bricht ein.","weiter":"c_gestaendnis"},"misserfolg":{"text":"„Gespart. Seit Jahren.“ Ohne mehr Beweise glaubt man {C}.","weiter":"ende_offen"}},{"text":"{B} beschuldigen","weiter":"ende_falsch"},{"text":"„Ich weiß es nicht sicher. Ich beschuldige niemanden.“","weiter":"ende_offen"}]},"c_gestaendnis":{"ort":"dorf","text":"{C} sackt in sich zusammen. „Sie haben gedroht, mein Haus anzuzünden. Dann haben sie bezahlt. Ich dachte, ein Wagen … was ist schon ein Wagen.“","optionen":[{"text":"Verbannung fordern","weiter":"ende_verbannt"},{"text":"„Hilf uns, die Räuber in eine Falle zu locken. Dann sehen wir weiter.“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":13},"erfolg":{"text":"{C} nickt, bleich. Mit einer falschen Nachricht lockt ihr die Räuber in einen Hinterhalt. Zwei werden gefangen, die anderen fliehen und kommen nicht wieder.","folgen":{"dorf":{"nahrung":15,"waren":3}},"weiter":"ende_falle"},"misserfolg":{"text":"{C} schüttelt nur den Kopf und weint. Das Dorf entscheidet sich für die Verbannung.","weiter":"ende_verbannt"}}]},"ende_verbannt":{"ort":"dorf","ende":true,"text":"{C} verlässt das Dorf am nächsten Morgen mit einem Bündel. Niemand winkt. Ein Teil der Vorräte bleibt verloren.","folgen":{"sym":{"A":3,"B":4,"C":-10},"merkt":{"C":"{held} hat mich überführt. Ich hätte es an deiner Stelle auch getan.","B":"{held} hat herausgefunden, dass ich es nicht war."},"chronik":["brett_spitzel_verbannt","Ich habe {C} als Spitzel der Räuber überführt. {C} musste gehen."],"dorf":{"stimmung":-2}}},"ende_falle":{"ort":"dorf","ende":true,"text":"Ein Teil der Vorräte kommt zurück. {C} darf bleiben – unter Aufsicht, mit gesenktem Kopf. Und das Dorf hat etwas über Gnade gelernt.","folgen":{"sym":{"A":3,"B":4,"C":5},"merkt":{"C":"{held} hat mir eine zweite Chance gegeben, obwohl ich das Dorf verraten habe."},"chronik":["brett_spitzel_falle","Ich habe {C} überführt – und mit einer Falle die Räuber gefasst."],"beute":{"stufe":3,"chance":0.6,"text":"Bei den gefangenen Räubern findet sich Beute aus anderen Überfällen. Ein Stück davon gibt dir das Dorf."}}},"ende_falsch":{"ort":"dorf","ende":true,"text":"{B} wird aus dem Dorf gejagt, schreiend, dass es nicht wahr ist. Zwei Wochen später werden wieder Vorräte überfallen.","folgen":{"sym":{"B":-12,"C":2},"merkt":{"B":"{held} hat mich für etwas verurteilt, das ich nicht getan habe."},"chronik":["brett_spitzel_falsch","Ich habe {B} des Verrats beschuldigt. Die Überfälle hörten nicht auf."],"dorf":{"stimmung":-4,"nahrung":-8}}},"ende_offen":{"ort":"dorf","ende":true,"text":"Ohne Urteil geht das Dorf auseinander. Das Misstrauen bleibt – wie ein Splitter unter der Haut.","folgen":{"dorf":{"stimmung":-2}}}}}},{"id":"b_damm","titel":"Wenn der Damm bricht","kurz":"Nach tagelangem Regen droht das alte Wehr oberhalb des Dorfes zu brechen. {A} schlägt Alarm.","schwierigkeit":3,"rollen":{"A":"Wer Alarm schlägt","B":"Wer am Ufer wohnt"},"def":{"start":"alarm","szenen":{"alarm":{"ort":"dorf","gefahr":true,"text":"Es ist Nacht und es schüttet. {A} hämmert an deine Tür. „Das alte Wehr! Es knirscht und ächzt. Wenn es bricht, steht das Unterdorf unter Wasser – das Haus von {B} zuerst!“","optionen":[{"text":"Zum Wehr laufen","weiter":"wehr"},{"text":"Erst das Unterdorf wecken","weiter":"wecken","folgen":{"flag":["gewarnt"]}}]},"wecken":{"ort":"dorf","text":"Du hämmerst an Türen. Leute stolpern verschlafen ins Freie, Kinder auf den Armen. {B} will nicht gehen. „Mein Vorrat! Meine Werkstatt!“","optionen":[{"text":"{B} mit Gewalt herausziehen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":12},"erfolg":{"text":"Du packst {B} und ziehst. {B} flucht – und dankt dir später.","folgen":{"flag":["b_sicher"]},"weiter":"wehr"},"misserfolg":{"text":"{B} reißt sich los und rennt zurück ins Haus.","weiter":"wehr"}},{"text":"{B} gut zureden","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":12},"erfolg":{"text":"„Dinge kann man ersetzen.“ {B} nickt und geht mit.","folgen":{"flag":["b_sicher"]},"weiter":"wehr"},"misserfolg":{"text":"{B} hört nicht zu.","weiter":"wehr"}}]},"wehr":{"ort":"wald","gefahr":true,"text":"Das Wehr ist ein alter Damm aus Stämmen und Steinen. Wasser schießt schon durch Lücken. Ein Stamm in der Mitte biegt sich bedrohlich.","optionen":[{"text":"Den Stamm mit Pfählen abstützen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":15},"erfolg":{"text":"Mit drei Pfählen und deinem ganzen Gewicht hältst du ihn. Leute aus dem Dorf schleppen Säcke voll Erde heran. Gegen Morgen hält das Wehr.","folgen":{"flag":["gehalten"]},"weiter":"morgen"},"misserfolg":{"text":"Der Stamm bricht mit einem Knall. Das Wasser reißt dich von den Füßen, du klammerst dich an eine Wurzel.","folgen":{"flag":["gebrochen"],"gefahr":2},"weiter":"morgen"}},{"text":"Einen Graben ausheben, damit das Wasser seitlich abläuft","tag":"[Altes Wissen]","probe":{"id":"altes_wissen","dc":14},"erfolg":{"text":"Du erinnerst dich an alte Wasserbauer: Entlasten statt halten. Ihr hebt am Rand einen Graben aus. Das Wasser findet den neuen Weg – das Wehr bleibt stehen, das Unterdorf trocken.","folgen":{"flag":["gehalten","graben"]},"weiter":"morgen"},"misserfolg":{"text":"Der Graben ist zu flach. Das Wehr bricht trotzdem, aber weniger heftig.","folgen":{"flag":["gebrochen","teil"]},"weiter":"morgen"}},{"text":"Das Wehr gezielt an der Seite öffnen, wo die Felder liegen","weiter":"morgen","ergebnis":"Du hebelst zwei Stämme heraus. Das Wasser schießt über die Felder statt durchs Dorf. Die Häuser bleiben trocken – die Wintersaat ist fort.","folgen":{"flag":["felder"]}}]},"morgen":{"ort":"dorf","text":"Der Morgen dämmert grau.","optionen":[{"text":"Nachsehen","wenn":{"flag":"gehalten"},"weiter":"ende_gehalten"},{"text":"Nachsehen","wenn":{"flag":"felder"},"weiter":"ende_felder"},{"text":"Nachsehen","wenn":{"flag":"gebrochen"},"weiter":"ende_flut"}]},"ende_gehalten":{"ort":"dorf","ende":true,"text":"Das Wehr hält. Schlammige, erschöpfte Menschen sitzen am Ufer und lachen, ohne zu wissen warum. {A} umarmt jeden, auch dich.","folgen":{"sym":{"A":5,"B":5},"merkt":{"B":"{held} hat in der Regennacht das Wehr gehalten. Mein Haus steht noch.","A":"{held} ist mit mir zum Wehr gelaufen, als alle anderen noch schliefen."},"chronik":["brett_damm_gehalten","In der Regennacht haben wir das alte Wehr gehalten."],"dorf":{"stimmung":5,"holz":-5},"beute":{"stufe":2,"chance":0.5,"text":"{B} schenkt dir zum Dank etwas aus der geretteten Werkstatt."}}},"ende_felder":{"ort":"dorf","ende":true,"text":"Kein Haus ist beschädigt, aber das Feld ist ein See. Im Frühjahr wird neu gesät werden müssen. Manche nennen es klug, andere hätten lieber gefragt werden wollen.","folgen":{"sym":{"B":4,"A":1},"chronik":["brett_damm_felder","Ich habe das Wehr zu den Feldern hin geöffnet, um das Dorf zu retten."],"dorf":{"nahrung":-20,"stimmung":-1}}},"ende_flut":{"ort":"dorf","ende":true,"text":"Das Unterdorf steht knietief im Schlamm. Vorräte sind verdorben, die Werkstatt von {B} ist verwüstet. Aber alle leben – zumindest dafür hat es gereicht.","folgen":{"sym":{"A":2,"B":1},"chronik":["brett_damm_flut","Das alte Wehr ist in der Regennacht gebrochen. Das Unterdorf wurde überflutet."],"dorf":{"nahrung":-25,"holz":-10,"waren":-3,"stimmung":-4}}}}}}]$q$::jsonb) e
on conflict (id) do update set titel = excluded.titel, beschreibung = excluded.beschreibung, kurz = excluded.kurz, art = excluded.art, schwierigkeit = excluded.schwierigkeit, rollen = excluded.rollen, def = excluded.def;
